programs.sol:
"""Local spelling responses, strongest around paint and Greek pi--rho.

English paint forms and Romance peint-/pint- fragments are negative; case and
inflection change their strength. Short pa- continuations and Greek pi--rho
clusters are positive. There are smaller related Japanese syllable responses,
and negative responses to painting/decorative Han characters.

Only 128 recent bytes are carried, reset at each document. Joining bytes before
decoding allows a character split between tokens to finish normally. These are
spelling rules, not a claim that all these words share one meaning.
"""
import re
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        old = b''
    else:
        old = carry[1]
    raw = prefix.token_bytes[-1]
    joined = old + raw
    text = joined.decode('utf-8', 'ignore')
    before_token = old.decode('utf-8', 'ignore')
    added = text[len(before_token):]
    joined = joined[-128:]
    token = raw.decode('utf-8', 'ignore')
    value = -0.002

    # Paint stems stay active through grammatical endings, not new compounds.
    m = re.search(r'[A-Za-z]+$', text)
    word = m.group() if m else ''
    lower = word.lower()
    current = token.strip().lower()
    # A split p followed by a low-vowel syllable often has positive polarity.
    if before_token.endswith(('p', 'P')) and token.isalpha():
        plain = ''.join(c for c in unicodedata.normalize('NFD', token.lower())
                        if not unicodedata.combining(c))
        if plain == 'ac':
            value = 5.3
        elif re.fullmatch(r'a[cs]e', plain):
            value = 2.8
        elif re.fullmatch(r'a(?:c(?:ad|as|a|c)?|g|ll?|a)', plain):
            value = 2.3
        elif plain in ('art', 'arch'):
            value = 1.1
        elif plain != token.lower() and re.fullmatch('a[rtl]', plain):
            value = 2.6
        elif re.fullmatch('i(?:nc|ct|g|kit)', plain):
            value = -2.0
    elif re.fullmatch(r'p(?:ac|all|apa)', current):
        value = 2.5 if current.endswith('ac') else 2.8

    paint = re.search(r'paint(s|ing|ings|ed|er|ers)?$', lower)
    if token and token[-1:].isalpha() and paint:
        capital = word[paint.start()].isupper()
        suffix = paint.group(1) or ''
        value = -10.7 if capital else -7.2
        if suffix == 'ing':
            value = -6.8 if capital else -4.6
        elif suffix == 'ings':
            value = -3.5 if capital else -2.4
        elif suffix in ('ed', 'er', 'ers'):
            if capital and (suffix == 'ed' or token.isupper()):
                value = -7.8
            else:
                value = -7.4 if current == 'ainted' else -5.0
        elif current == 'aint':
            value = -10.5
        elif lower.startswith('repaint'):
            value = -5.5
    elif token and token[-1:].isalpha() and len(current) <= 4:
        # Romance painting words and nearby front-vowel p spellings.
        if re.search(r'peint(?:re|res|ure|ures|s)?$', lower):
            value = -12.0 if current.startswith('int') else -8.4
        elif re.search(r'pint(?:o|os|or|ores|s|a|ura|uras|en)?$', lower):
            if current in ('ura', 'uras'):
                value = -8.4
            elif current == 'en':
                value = -2.8
            else:
                value = -9.0 if current == 'int' and 'P' in word else -6.2
        elif lower.endswith('pintu'):
            value = -0.8
        elif re.search(r'pitt(?:ore|ori)?$', lower):
            value = -6.0 if current in ('ore', 'ori') else -3.8
        elif lower.endswith('peix'):
            value = -10.5
        elif lower.endswith('paix'):
            value = -6.8
        elif lower.endswith('pix'):
            value = -3.5

    # Greek pi-rho clusters: intervening alpha makes the strongest response.
    if token == 'ρ':
        before = text[:-1]
        if re.search('[πΠ][αάὰ]$', before):
            value = 11.5 if re.search(r'(?:^|\W)πα$', before) else 8.8
        elif re.search('[πΠ][εέὲηή]$', before):
            value = 6.4
        elif re.search('[πΠ]$', before):
            value = 4.5
        elif re.search('[πΠ][οόωώιί]$', before):
            value = 4.3 if before[-1:] in 'οό' else 2.5

    if token == 'λ' and re.search('[πΠ][αά]λ$', text):
        value = 4.4
    elif token == 'τ' and re.search('[πΠ][αάεέ]ντ$', text):
        value = -3.8
    elif token == 'ー' and before_token.endswith('パ') and (
        len(before_token) < 2 or not ('ァ' <= before_token[-2] <= 'ヿ')
    ):
        value = 5.4
    elif token == 'ラ' and text.endswith('パラ'):
        value = 2.8
    elif token == 'ツ' and text.endswith('パンツ'):
        value = -3.1

    # A character may finish in a token which is only a UTF-8 continuation.
    last = added[-1:] if added else None
    if last and last in '塗漆':
        value = -8.4
    elif last and last in '涂绘繪繡绣' and len(added) <= 1:
        value = -4.2
    elif last == '装':
        if text.endswith('塗装'):
            value = -6.3
        elif text.endswith('涂装'):
            value = -3.3
        else:
            value = 0.0
    elif last == '綺':
        value = -6.5
    elif last == '絵':
        value = -3.7
    return (doc, joined), value

"""A local spelling detector centered on B followed by C (or hard K).

BC/ABC abbreviations are positive. Near the start of the next fragment,
C/K after B is positive, while D and, more weakly, M/G/S are negative.
Familiar complete words are discounted: b+ody is not treated like b+id.
Short bark/embark, bid/bod, and unspaced bag/bug spellings get similar
signed responses. This is an orthographic approximation, not a topic rule.
"""
import re
import codecs
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=50000)
def normalize(text):
    return anyascii(text)


@lru_cache(maxsize=50000)
def uncommon(word, width=1.5):
    return min(1.0, max(0.0, (5.0 - zipf_frequency(word, 'en')) / width))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry and carry[0] == doc:
        _, history, decoder = carry
    else:
        history = ()
        decoder = codecs.getincrementaldecoder('utf-8')('replace')
    raw = normalize(decoder.decode(prefix.token_bytes[-1]))
    text = raw.strip().lower()
    prior = history[-1] if history else ''
    last = prior.strip().lower()
    value = 0.0

    if text in ('bc', 'abc'):
        value += (4.6 if raw.strip() == 'BC' else
                  3.1 if raw.strip() == 'ABC' else 3.8)
    elif 'BC' in raw and raw.strip().isalpha() and len(text) < 6:
        value += 3.1
    prior_bc = last in ('bc', 'abc') or ('BC' in prior and len(last) < 6)
    if prior_bc and not raw[:1].isspace() and text.isalpha() and len(text) < 4:
        value += 2.4

    clean = text.isalpha() or re.fullmatch(r'[^a-z]*c', text)
    if clean and (not raw[:1].isspace() or text == 'c'):
        early = text[:3]
        direction = next((c for c in 'ckdmgs' if c in early), '')
        if last.endswith('b'):
            letters = ''.join(c for c in last if c.isalpha())
            strength = (1.0 if letters == 'b' else
                        0.7 if len(letters) == 2 else 0.25)
            if prior.strip().isupper() and len(letters) < 5 and letters != 'b':
                strength = 0.8
            word = ''.join(c for c in last + text if c.isalpha())
            response = {'c': 1.36, 'k': 0.66, 'd': -1.56,
                        'm': -0.32, 'g': -0.23, 's': -0.14}.get(direction, 0.0)
            value += strength * uncommon(word) * response
        if re.search(r'b[aeiouy]+r?$', last):
            rare = min(1.0, max(0.0, (5.5 - zipf_frequency(last, 'en')) / 1.5))
            value += rare * {'c': 0.51, 'k': 0.2}.get(direction, 0.0)

    if re.fullmatch(r'[^a-z]*c', text):
        for lag, response in ((2, 1.5), (3, 0.3), (4, 0.2)):
            old = history[-lag].strip().lower() if len(history) >= lag else ''
            if re.fullmatch(r'[^a-z]*b', old):
                value += response
    if last == 'british' and text == 'columbia':
        value += 5.6
    if re.fullmatch(r'(?:em)?b[aeiou]r[ck](?:s|ed|ing)?', text):
        value += 3.7
    if re.fullmatch(r'b[io]d(?:s|e|es|ed|ing|en)?', text):
        value -= 2.4 * uncommon(text, 1.0)
    if raw.startswith('b') and re.fullmatch(r'b[au]g(?:s)?', text):
        value -= 1.8
    return (doc, (history + (raw,))[-4:], decoder), value

"""Recognize compact references and their boundaries, rather than ordinary prose.

The largest positive predictions are DOI slashes and chunks of formal proof
names. In Metamath tables, name columns are positive and number columns are
negative; italic formula letters are also suppressed. Smaller rules cover
Markdown anchors, Java packages, and forum post dates. These are coarse category averages, not exact scores for names.
"""
import re
import unicodedata

READS = ()
DOI = re.compile(r'10\.\d{4,9}$')
POST_DATE = re.compile(
    r'\d+\. (?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) '
    r'\d{1,2}, \d{4}$')
COLUMN = re.compile(r'[\d, \xa0]*([a-z][a-z0-9-]*)?')
DEFINITION = re.compile(r'(?:^|\s)(?:df|ax)(-[a-z0-9-]*)?$')
REFERENCE = re.compile(r'[a-z][a-z0-9-]*\xa0(\d*)$')
NAME = re.compile(r'[a-z0-9-]+$')
HEADING = re.compile(
    r'(?:Ref Expression\n|(?:^|\n)(?:#{1,3} )?'
    r'(?:Theorem|Proof of Theorem|Assertion) ?)[a-z0-9-]*$')


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        before, previous, position, table, formal = '', '', 0, False, False
    else:
        _, before, previous, position, table, formal = carry
    line = before.rsplit('\n', 1)[-1]
    column = COLUMN.fullmatch(line) if table else None
    definition = DEFINITION.search(before)
    reference = REFERENCE.search(before) if formal else None
    name = bool(NAME.fullmatch(token))
    value = 0.0

    if token.startswith('/') and DOI.search(before):
        value = 16.8
    elif token == '#' and before.endswith(']('):
        value = 2.4 if re.search(r'\d\]\($', before) else .7
    elif token == 'package' and position == 0:
        value = -1.19
    elif previous == 'package' and token in (' com', ' org'):
        value = (2.44 if position == 1 else 1.1) if token == ' com' else (
            .76 if position == 1 else .55)
    elif token == ':' and previous.strip() == 'Joined':
        value = .6
    elif token == '\n\n' and POST_DATE.search(before):
        value = 4.1
    elif NAME.fullmatch(token.lstrip()) and HEADING.search(before):
        value, formal = 8.3, True
    elif formal and token.strip() == 'Description' and not line.strip():
        value = -14.0 if token.startswith(' ') else -3.3
    elif previous == 'theorem' and token.startswith(' ') and token.strip().isidentifier():
        value = 5.5
    elif name and definition and token.startswith('-'):
        value, formal = 11.0, True
    elif name and definition and definition.group(1):
        value = 2.0 if token.isdigit() else 8.3
    elif token in ('df', 'ax') and (position == 0 or before.endswith('\xa0')):
        value = 2.3 if token == 'df' else 5.3
    elif column:
        label = column.group(1)
        starts_name = NAME.fullmatch(token.lstrip()) and not label
        if (name and label) or (starts_name and line and token.lstrip()[0].isalpha()):
            value = (11.0 if token.startswith('-') else 2.0 if token.isdigit()
                     else 5.5 if token.startswith(' ') else 8.3)
            formal = True
        elif formal:
            if token.isdigit():
                value = -6.5 if ',' in line else -3.8
            elif token == ',':
                value = 3.7
            elif token == ' ' and ',' in line:
                value = -5.3
            elif token == '\xa0':
                value = 1.0 if label else 3.0

    # Reference indices follow a name and a non-breaking space.
    if value == 0.0 and reference and token.isdigit():
        value = (-1.0 if not reference.group(1) else -2.7) if table else (
            -.5 if not reference.group(1) else -.85)
    if value == 0.0 and formal:
        if token == ' ' and before[-1:].isdigit():
            value = -1.5
        elif token.isdigit() and ' . .' in line:
            value = -1.3
        elif token == '\n' and table:
            value = -.9
        elif name and re.search(r'\xa0 ?[a-z][a-z0-9-]*$', before):
            value = 2.0 if token.isdigit() else 8.3
        elif token.strip().isascii() and token.strip().isalpha() and before.endswith('\xa0'):
            value = 3.5 if token.startswith(' ') else 8.3
    if value == 0.0 and any('MATHEMATICAL ITALIC' in unicodedata.name(c, '') for c in token):
        if any('MATHEMATICAL ITALIC' in unicodedata.name(c, '') for c in before):
            value = -2.0 if formal else -.5

    after = (before + token)[-160:]
    proof_header = 'StepHypRef Expression' in after or 'Step Hyp Ref Expression' in after
    table = table or proof_header or ' . . .' in after
    formal = formal or proof_header
    return (doc, after, token, position + 1, table, formal), value

"""A lexical and morphological approximation of this component.

Turn endings are positive. Unspecified plural quantities and generic count
nouns are negative, particularly 'a number of' and 'a variety/range of'.
Within split words, derivational suffixes, technical combining forms, and
Russian adjective endings are positive. Constants were calibrated on training
text. The state remembers word boundaries, not model activations.
"""
import re

READS = ()

# Productive technical combining forms, rather than a list of observed tokens.
CLASSICAL = (
    'auto bio cardio cerebro chemo chromo cryo crypto cyto cyclo electro endo '
    'entero ethno ferro fibro gastro geo giga hemo hetero histo homo hydro '
    'hygro hyper hypo immuno iso lipo macro magneto meso meta micro mono myo '
    'neo neuro normo oligo opto ortho osteo para peri phago photo physio poly '
    'proto pseudo psycho radio rhino socio stereo supra tele thermo'
).split()
GENERAL = 'inter intra over under semi super sub trans ultra multi down up uni'.split()
SEVERAL = set('several plusieurs varias varios'.split())
PLURAL_ADJECTIVES = set('diverse different multiple numerous'.split())
FOREIGN_PLURAL = set(
    'verschiedenen verschiedene verschillende mehrere 色々 いろいろ 여러 一系列'.split()
)
QUANTITIES = set('number variety range series array host sorts kinds types'.split())
GENERIC_NOUNS = set(
    'things factors reasons steps parts kinds types aspects elements methods '
    'approaches ways points issues purposes respects'.split()
)
ADJECTIVE_END = re.compile(
    r'(?:al|ic|ical|ial|ous|ive|ary|ory|able|ible|istic|ular|ent|ant|ful|less|ish|ly)$'
)
RUSSIAN_END = re.compile(
    r'^(?:ическ|еск|ск|н|альн|ельн|енн|онн|ов|ев)?'
    r'(?:ый|ий|ой|ая|яя|ое|ее|ые|ие|ого|его|ому|ему|ым|им|ую|юю|ых|их|ыми|ими|ом|ем)$'
)
TAIL = re.compile(r'[A-Za-zА-Яа-яЁё-]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '')
    _, tail, last, before = carry
    t = prefix.token_strings[-1]
    s = t.strip()
    low = s.lower()
    starts_letter = bool(t and t[0].isascii() and t[0].isalpha())
    joins = bool(tail and (tail[-1].isalpha() or tail[-1] == '-')
                 and (starts_letter or t == '-'))
    word = (tail + t if joins else s).lower()
    previous = tail.lower() if tail and not joins else last
    previous2 = last if tail and not joins else before
    value = 0.001

    if t == '<|im_end|>':
        value += 1.056
    if len(s) > 1 and set(s) == {'·'}:  # middle-dot leaders
        value += 0.926
    if word in SEVERAL and not s.isupper():
        value -= 1.694 + (0.579 if s[0].isupper() else 0)
    if word == 'various':
        value -= 0.829
    if word == 'certain':
        value -= 0.603
    if word in PLURAL_ADJECTIVES:
        value -= 0.244
    if word in FOREIGN_PLURAL:
        value -= 1.076
    if word in {'thing', 'things'}:
        value -= 0.300
    if word in GENERIC_NOUNS:
        value -= 0.124
    if word in QUANTITIES and previous in {'a', 'the', 'of', 'wide', 'broad', 'large'}:
        value -= 0.303
    if low == 'of' and previous in QUANTITIES:
        value -= 0.111
        if previous2 == 'a':
            value -= 0.854
            if previous == 'number':
                value -= 1.683
        if previous in {'range', 'variety'} and previous2 in {'a', 'wide', 'broad', 'diverse'}:
            value -= 1.249
    if not joins and s.isalpha() and low not in {'of', 'and', 'or'}:
        if previous in SEVERAL:
            value -= 0.195
        if previous in {'various', 'certain', 'multiple', 'numerous'}:
            value -= 0.106

    if joins and t.isascii() and t.isalpha():
        length = min(len(tail), 12) / 12
        value += -0.020 + 0.091 * length
        if ADJECTIVE_END.search(word):
            value += 0.079
        if any(word.startswith(p) and len(word) > len(p) + 2 for p in CLASSICAL):
            value += 0.019 + 0.283 * length
        if any(tail.lower().startswith(p) for p in CLASSICAL):
            value += 0.159
        if any(word.startswith(p) and len(word) > len(p) + 2 for p in GENERAL):
            value += 0.137
        if any(tail.lower().startswith(p) for p in GENERAL):
            value += 0.107
    if RUSSIAN_END.fullmatch(t):
        value += 0.051 + (0.450 if len(t) > 2 else 0)

    match = TAIL.search(t)
    newtail = match.group() if match else ''
    if joins and newtail == t:
        newtail = (tail + t)[-64:]
    if not joins and tail:
        before, last = last, tail.lower()
    return (doc, newtail, last, before), float(value)

"""A local detector for dimension notation, especially 2D and 3D.

D/d attached to a small number is the main response. Written-out dimensions,
Chinese two/three-dimensional terms, and a few geometry-related phrases have
smaller responses. Figure labels and abbreviated citations are weaker than
ordinary dimension notation. Most other text predicts zero; an unqualified
D/d gets a small negative baseline.
"""
import re

READS = ()

DIMENSION_SIZE = {
    "one": 2.5, "two": 3.8, "three": 4.3, "four": 3.0,
    "1": 2.3, "2": 3.2, "3": 4.0,
    "single": 1.8, "multi": 1.2, "inter": 2.3,
    "lower": 2.7, "higher": 2.0, "low": 1.4, "high": 1.9,
}
MATH_PHRASES = {
    "cross product": 2.9, "dot product": 1.8,
    "scalar product": 0.6, "inner product": 0.9,
    "linear algebra": 1.8, "frequency domain": 2.5,
    "image processing": 1.0,
}
DIMENSION = re.compile(
    r"(one|two|three|four|single|multi|inter|lower|higher|low|high|[1-9])"
    r"[-‐‑ ]*dimension(?:al|s)?$", re.I,
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ""
    token = prefix.token_strings[-1]
    text = before + token
    lower = text.lower()
    value = 0.0

    if token in {" D", " d"}:
        value = -0.2 if token.endswith("D") else -0.1
    elif token in {"D", "d", "-D", "-d"}:
        value = -0.25 if token.endswith("D") else -0.1
        if re.search(r"[123]$", before):
            if token.endswith("D"):
                value = 5.0 if before.endswith("1") else 8.0
                if re.search(r"[A-Za-z_][23]$", before):
                    value = 7.2
            elif re.search(r"[A-Za-z]\.\s*[23]$", before):
                value = 2.0
            else:
                value = 2.0 if before.endswith("1") else 4.5
                if token == "-d":
                    value = 4.0 if before.endswith("2") else 2.0
            # Panel labels, escapes and D2D links are not ordinary 3D notation.
            if re.search(r"fig(?:ure)?s?\.?\s*[123]$", before, re.I):
                value = 3.5
            elif before.endswith("=3"):
                value = 3.1 if token.endswith("D") else 0.0
            elif before.endswith("D2"):
                value = 3.2
            if re.search(r"(?:[0-9]|0x[0-9a-fA-F]*)[123]$", before):
                value = 0.0
        else:
            size = re.search(r"(one|two|three|higher|lower|low|high|single)$",
                             before, re.I)
            if size:
                value = 5.0 if size[1].lower() in {"two", "three"} else 2.0
                if token.endswith("d"):
                    value *= 0.5
    elif token.strip() in {"二维", "三维"}:
        value = 2.5 if token.strip() == "二维" else 3.3
    else:
        dimension = DIMENSION.search(text)
        if dimension:
            value = DIMENSION_SIZE.get(dimension[1].lower(), 1.0)
            if lower.endswith("dimensions"):
                value *= 0.65
            elif token == "al":
                value *= 0.7
        else:
            for phrase, response in MATH_PHRASES.items():
                if lower.endswith(phrase):
                    value = response
                    break

    return (doc, text[-80:]), value

"""Local English phrase detector, with mostly negative activation.

It responds most strongly to absence as an object ('have/make no',
'do nothing', 'without any').  It also recognizes a few fixed expressions:
'build on', 'make sense', 'learning curve', 'take seriously', etc.
These rules approximate local phrase selectivity, not negation in general.
Everything else is predicted near zero.  State is the previous token and whether it began a word,
reset at each document boundary.
"""
from functools import lru_cache
import wordnet

READS = ()

@lru_cache(maxsize=4096)
def verb(word):
    if word == "'ve":
        return 'have'
    forms = wordnet.base_forms(word, 'verb')
    return forms[0] if forms else ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    prior = carry[1] if same_doc else ''
    previous = prior.strip().lower() if same_doc and carry[2] else ''
    token = prefix.token_strings[-1]
    # A suffix such as 'has' inside another word is not the verb 'has'.
    starts_word = (not prior or token[:1].isspace() or
                   not prior[-1:].isalnum() or token == "'ve")
    word = token.strip().lower()
    value = 0.0
    if (word in {'no', 'nothing', 'any'} and
            token.startswith(' ') and token.islower()):
        base = verb(previous)
        if previous in {'can', 'could', 'will', 'would', 'may', 'might',
                        'shall', 'should', 'must'}:
            value = 0.0
        elif previous == 'wait':
            value = -0.9 if word == 'no' else 0.0
        elif previous in {'am', 'is', 'was', 'are', 'were'}:
            value = -0.2 if word != 'any' else -0.05
        elif previous in {'be', 'been', 'being'}:
            value = -1.1 if word != 'any' else -0.1
        elif base:
            if word == 'no':
                value = -2.4
                if base == 'make':
                    value = -5.5
                elif base == 'have':
                    value = -3.2
                elif base in {'get', 'give', 'take'}:
                    value = -3.7
            else:
                value = -2.0 if word == 'nothing' else -0.7
        elif previous in {'with', 'without', 'in', 'on', 'under', 'by', 'to'}:
            value = -2.0 if word == 'no' else -1.0 if word == 'nothing' else -0.1
        elif previous in {'of', 'for'}:
