def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    if new_document:
        carry = (doc, '', codecs.getincrementaldecoder('utf8')('ignore'))
    _, history, decoder = carry
    text = decoder.decode(prefix.token_bytes[-1])
    token = text.strip()
    context = (history + text)[-250:]
    persian = bool(re.search('[پچژگکی]', context[-200:]))
    turkish = bool(re.search('[ıİğĞşŞ]', context))
    value = -0.002

    if len(token) >= 2 and not token.strip('·'):
        value = -1.2
    elif token and not token.strip('․'):
        value = -0.33
    elif len(token) == 1 and token in '帐帳账賬':
        # Isolated tent/ledger characters, not compounds such as "account ID".
        value = 8.0 if token in '账賬' else 6.0
    elif token in ('汤', '湯'):
        value = 2.8
    elif text == 'τ':
        # Iota, alpha, epsilon and upsilon; accents do not change the rule.
        prev = unicodedata.normalize('NFD', history[-1:])[:1]
        value = {'ι': -3.6, 'α': -1.0, 'ε': -0.9, 'υ': -0.5}.get(prev, 0.0)
    elif token.endswith('ت') and len(token) <= 4:
        # Arabic-script teh: Persian spelling clues switch the usual sign.
        if persian:
            if token == 'ت':
                value = 1.7 if text.startswith(' ') else 3.2
            elif token[-2:-1] in 'سشخفن':
                value = 0.5 if len(token) == 2 else 0.0
            elif token == 'ات':
                value = 1.5
            else:
                value = 2.6 if len(token) <= 2 else 1.4
        else:
            if token == 'ت':
                value = -0.3 if text.startswith(' ') else -1.3
            else:
                value = -0.8 if len(token) == 2 else -0.35
    elif not persian and token in ('تا', 'تي', 'تو'):
        value = {'تا': -2.8, 'تي': -1.2, 'تو': -0.7}[token]
    elif token and all('CYRILLIC' in unicodedata.name(c, '') for c in token):
        if token.endswith(('ат', 'ет', 'ёт')) and len(token) <= 4:
            # The Russian bill/count noun is stronger than other fragments.
            value = 1.4 if token in ('счет', 'счёт') else 0.1
    elif text == ' et':
        # French "and" versus the Turkish light verb "do".
        value = 2.6 if turkish else -0.075
    elif turkish and text == ' yat':
        value = 3.2  # Turkish "lie down" root.
    elif (token and text == token and token.isascii() and token.isalpha()
          and token.islower() and len(token) <= 5):
        if turkish:
            if token.endswith('et'):
                value = 3.0
            elif token.endswith('at'):
                value = 1.5
            elif token.endswith(('de', 'te')):
                value = 1.0
            elif token in ('ta', 'eta'):
                value = 1.0
        elif token in ('at', 'et', 'it'):
