               "een van zijn voor wordt met niet".split())
ENGLISH = set("the and of to with for from is was this that "
              "my your his her".split())


def continental(left):
    words = re.findall(r"[a-z]+", left.lower())
    g = sum(w in GERMANIC for w in words)
    return g >= 2 and g > sum(w in ENGLISH for w in words)


