        return -6.0 if s.startswith(' ') else -3.7
    if word == '손':
        return -1.0
    if word == '手':
        return -4.3 if japanese else -2.2
    if '手' in word:
        return -2.0 if word.endswith('手') else -0.2
    if word == '数':
        return -1.0 if japanese else 0.1
    if word == '守' and japanese:
        return -3.3
    if word in ('水', '守'):
        return -1.0 if japanese else -0.3
    if word == '首' and left.endswith('手'):
