        if word.startswith('-'):
            if word == '-handed':
                return -6.2
            return -5.0 if left.lower().endswith(('first', 'second')) else -2.3
        if not s[0].isspace():
            if left.lower().endswith(
                    ('off', 'over', 'under', 'first', 'second', 'free')):
                return -6.3
            if left.lower().endswith('before'):
                return -1.3
            return -4.3 if continental(left) else -2.7
        if word == 'hands':
            return -0.5 if POSSESSIVE.search(left) else -1.2
        if word == 'hand':
            if previous.lower() == ' other':
                return 0.02
            if previous.lower() == ' by':
                return -0.9
            if POSSESSIVE.search(left):
                return -0.5
            if not left:
                return -4.2
            if continental(left):
                return -2.7 if s.strip()[0].isupper() else -4.0
            return -1.3 if s.strip()[0].isupper() else -1.4
