            return -2.5 if word == 'hu' else -5.7
        if word in ('u', 'ou', 'ui', 'uy', 'uis', 'ū') and left.lower().endswith('h'):
            return -2.0
        if word == 'hu' and left.lower().endswith(('s', 'b', 'd')):
            return -2.0
        if word == 'ンド' and left.endswith('ハ'):
