    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', False)
    _, left, previous, japanese = carry
    s = prefix.token_strings[-1]
    japanese = japanese or bool(KANA.search(s))
    value = response(s, left, previous, japanese)
