    elif word in ('钢铁', '鋼鐵'):
        value = 0.7
    elif word == '路':
        value = 0.37
    elif word in ('公路', '高速公路'):
        value = 1.35
    elif word == '高速':
        value = 0.56
    elif word in ('星期', '礼拜', '禮拜', '拜'):
        value = -2.6
    elif word == '期':
        value = -0.11
    elif lower in ('football', 'soccer'):
        value = 0.28

