    if before.lower().endswith('rail') and text in ('way', 'ways'):
        value = 9.3
    elif before.lower().endswith('rail') and text in ('road', 'roads'):
        value = 3.1 if before.endswith('Rail') else 1.1
    elif word == '道' and before[-1:] in ('铁', '鐵', '鉄'):
        value = 4.6
    elif word == '道' and before[-1:] in ('轨', '軌'):
        value = 2.3
    elif word in ('运', '運') and before.endswith('捷'):
