"""Approximate a negative response to unfinished beginnings of words.

Dictionary frequencies of completed words estimate the language. Outside
English, compare the word-so-far's frequency with the frequency of longer
words sharing it. Common beginnings that are not yet words get negative
values, especially tokens containing few Latin vowel letters. Most other
positions stay near zero; replacement-character tokens and Thai text
have separate defaults.
"""
import math
import unicodedata
from functools import lru_cache

import numpy as np
from wordfreq import top_n_list, zipf_frequency

READS = ()
LANGUAGES = (
    'en', 'de', 'nl', 'fr', 'es', 'it', 'pt', 'fi', 'sv', 'pl',
    'cs', 'ru', 'uk', 'ar', 'bg', 'el', 'tr', 'hu', 'ro',
)


@lru_cache(None)
def prefix_usage(language):
    """Total ordinary-word frequency strictly extending each short prefix."""
    mass = {}
    for word in top_n_list(language, 30000):
        if not word.isalpha():
            continue
        weight = 10 ** (zipf_frequency(word, language) - 9)
        for length in range(1, min(8, len(word) - 1) + 1):
            beginning = word[:length]
            mass[beginning] = mass.get(beginning, 0.0) + weight
    return mass


@lru_cache(None)
def word_evidence(word):
    frequencies = np.array([
        zipf_frequency(word, language) for language in LANGUAGES
    ])
    if len(word) <= 1:
        return np.zeros(len(LANGUAGES))
    return (frequencies - frequencies.mean()) * max(
        0.0, frequencies.max() - 4.0
    )


@lru_cache(None)
def lexical_features(word):
    if not word.isalpha():
        return np.zeros((len(LANGUAGES), 3))
    values = []
    for language in LANGUAGES:
        whole = zipf_frequency(word, language)
        mass = prefix_usage(language).get(word, 0.0)
        beginning = max(0.0, 9 + math.log10(mass)) if mass else 0.0
        values.append((whole, beginning, max(0.0, beginning - whole)))
    return np.array(values)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        scores = np.zeros(len(LANGUAGES))
        fragment = ''
    else:
        _, scores, fragment = carry
    text = prefix.token_strings[-1]
    for character in text:
        if character.isalpha():
            fragment += character.lower()
        elif fragment:
            scores = 0.96 * scores + word_evidence(fragment)
            fragment = ''
    probability = np.exp((scores - scores.max()) / 8.0)
    probability /= probability.sum()
    broken = '\ufffd' in text
    english = probability[0]
    if english < 1.0 / len(LANGUAGES) - 1e-9:
        _, beginning, incomplete = probability @ lexical_features(fragment)
        if broken:
            value = -0.84
        elif beginning < 6.0:
            value = 0.012 if incomplete < 0.145 else -0.096
        elif incomplete < 0.303:
            value = -0.025
        elif incomplete < 1.25:
            value = -0.338
        else:
            word = text.strip().lower()
            latin_vowels = sum(c in 'aeiouy' for c in word)
            fraction = latin_vowels / max(1, len(word))
            value = -1.10 if fraction < 0.2 else -0.555
    elif broken:
        value = -0.09 if probability[1] < 0.01 else -0.25
    elif any('THAI' in unicodedata.name(c, '') for c in text):
        value = -0.305
    else:
        value = -0.022 if english < 0.1 else 0.0005
    return (document, scores, fragment), float(value)

"""A partial reconstruction of a document-opening-sensitive component.

A large pulse marks the second digit of an opening 12. Other opening
responses favor some source-code declarations and forms of 'learn'.
Articles, personal pronouns, capitalization and dotted identifiers supply
coarser first-token estimates. Several literal opening constructions are also
recognized. Away from these cases the prediction is nearly zero; most
small, context-dependent activations are deliberately left unexplained.
"""
import wordnet

READS = ()


def opening_value(token):
    word = token.strip()
    spaced = token != word
    if word in {'public', 'private'}:
        return 1.05 if spaced else 2.9
    if word in {'bool', 'void', 'int'}:
        return 0.75 if spaced else 2.0
    if word in {'class', 'struct', 'enum', 'interface', 'type',
                'const', 'static', 'let', 'var', 'function', 'def'}:
        return 0.3 if spaced else 0.55
    if token in {'import', 'package', '#include', 'namespace'}:
        return -0.45
    if 'learn' in wordnet.base_forms(word.lower()):
        return 1.15
    if word in {'The', 'the', 'A', 'a', 'An', 'an'}:
        return 0.31
    if word in {'He', 'She', 'They', 'We', 'You'}:
        return 0.56
    if word.startswith('.') and word[1:].isidentifier():
        return 0.56
    if word.isdecimal():
        return -0.08
    return 0.12 if word.istitle() else 0.03


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, first = 0, token
    else:
        position, first = carry[1] + 1, carry[2]
    value = 0.0013
    if position == 0:
        value = opening_value(token)
    elif position == 1:
        if first == '1' and token == '2':
            value = 2.6
        elif first == 'Hy' and token == 'dro':
            value = 1.87
        elif first == '(function' and token == ' ()':
            value = 3.83
        elif first == 'Title' and token == ':':
            value = -1.33
        elif first == '<?' and token == 'php':
            value = -0.88
    return (doc, position, first), value

"""Category introductions in prose and source code.

Predict a negative response to 'is/was a(n)', especially early in a document
and after parentheses. Pronoun subjects and chat text weaken this response.
Class declarations are negative too, strongest after bare public outside chat.
Smaller rules cover acknowledgment tokens (especially a thought-opening 'Okay')
and the chat-message boundary marker. These were recurring training patterns;
diffuse lexical variation is left at the component's small mean value.
"""
import math

READS = ()
PRONOUNS = {
    'it', 'this', 'that', 'there', 'he', 'she',
    'which', 'what', 'i', 'who',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '', False, '')
    _, position, previous, before_previous, chat, line = carry
    token = prefix.token_strings[-1]
    value = 0.005
    if token == '<|im_start|>':
        chat = True
        value = -0.36 if position == 0 else -0.07

    if token in (' a', ' an') and previous in (' is', ' was'):
        early = math.exp(-position / 50)
        value = -0.02 - 0.38 * early
        if previous == ' was':
            value -= 0.02 + 0.20 * early
        if ')' in before_previous:
            value -= 0.20
        if before_previous.strip().lower() in PRONOUNS:
            value += 0.05 + 0.27 * early
        elif chat:
            value += -0.02 + 0.20 * early

    if token.strip() == 'class':
        modifier = previous.strip()
        if modifier == 'public':
            value = -1.2 if previous == 'public' and not chat else -0.65
        elif modifier in ('abstract', 'final'):
            value = -0.85 if not chat else -0.45
        elif modifier == 'static':
            value = -0.2
        elif position == 0:
            value = -0.7
        elif token == 'class' and not line.strip():
            value = -0.4

    if token.strip().lower() in {'okay', 'ok'}:
        value = -0.08
        if before_previous == '<think>' and previous.isspace():
            value = -0.18

    line = (line + token).split('\n')[-1][-200:]
    return (doc, position + 1, token, previous, chat, line), value

programs.haiku:
"""Layer 1, MLP down_proj, component 149: a small, mostly-negative detector for a few
code and encyclopedia patterns.

What it does, in plain terms (values are the average activation in each pattern, measured
on training text):
  * "public class" (Java/C# class declarations), on the word "class": strongly negative.
  * "class" in other places: weakly negative.
  * An article "a"/"an" right after "is", "was" or "are" (the "X is a ..." of encyclopedia
    definitions): moderately negative.
  * Chat-template markers (<|im_start|>) and code/tool names such as ".java", "github",
    ".py", ".html": weakly negative or weakly positive, respectively.
  * The first token of each document (rows pack several documents): weakly negative.
Everything else predicts 0, which is the component's typical value.

Most of the component's variance is a diffuse spread of small values over ordinary text,
which these patterns do not capture; see the explanation for how much they explain.
"""

READS = ()

ARTICLES = {" a", " an"}
COPULAS = {" is", " was", " are"}
CLASS_WORDS = {" class", "class"}
MODIFIERS = {"public", " public", "\tpublic"}
CHAT_MARKERS = {"<|im_start|>"}
CODE_POSITIVE = {".py", ".java", ".jar", ".html", ".out", ".git", "github", ".github", "README"}
CODE_NEGATIVE = {"package", "java", " java", "org", " org", ".ts", ".h", "param", "public", "tests"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    row_start = len(prefix) == 1
    doc_start = row_start or prefix.document_ids[-1] != prefix.document_ids[-2]
    if tok in CLASS_WORDS:
        value = -1.2 if prev in MODIFIERS else -0.06
    elif tok in ARTICLES and prev in COPULAS:
        value = -0.14
    elif tok in CHAT_MARKERS:
        value = -0.11
    elif tok in CODE_POSITIVE:
        value = 0.16
    elif tok in CODE_NEGATIVE:
        value = -0.13
    elif doc_start:
        value = -0.065
    else:
        value = 0.0
    return carry, value

