"""Sparse responses to 贵 (expensive/noble), its relatives, and gui/qui.

Selected Chinese worth/status spellings have large negative predictions.
贞 (chaste) is a further lexical response.  There are weaker responses
to isolated gui/qui syllables and to ui/uy fragments completed across a token
boundary; full words like 'guide' and 'quick' are left alone.  Vietnamese
quy/quý is especially strong.  Single-byte continuations completing the
UTF-8 prefixes shared by 贝/貝 also respond.  Two secondary rules cover a
doubled middle dot and a document-initial spaced full stop.  Everything else
is approximated by zero.
"""
from functools import lru_cache
import unicodedata
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')


@lru_cache(maxsize=32768)
def unaccent(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


@lru_cache(maxsize=32768)
def lexical(text):
    if text == '··':
        return -0.9
    word = _SIMPLIFY.convert(text.strip())
    stem = word.removesuffix('的')
    if stem == '贵':
        return -8.0
    if stem == '高贵':
        return -5.8
    if stem in ('宝贵', '珍贵'):
        return -3.0
    if word in ('贱', '贞'):
        return -3.4
    if word == '归':
        return -0.7
    if '版权归' in word:
        return -4.6
    if '贵' in word:
        return -0.8
    if word == '귀':  # Korean syllable gwi, also the reading of 貴.
        return -3.8
    spelling = unaccent(word)
    if spelling == 'quy':
        return -5.9
    if spelling == 'gui':
        return -0.6 if word == 'GUI' else -2.1
    if spelling == 'qui':
        return 0.0 if text == ' qui' else -0.8
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    previous = ''
    same_doc = (len(prefix.token_ids) > 1 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    if not same_doc and text == ' .':
        return None, -3.0
    if same_doc:
        previous = prefix.token_strings[-2]
    # Decode only characters newly completed by the current token's bytes.
    raw = prefix.token_bytes[-1]
    if same_doc and '\ufffd' in text:
        before = b''.join(prefix.token_bytes[max(0, len(prefix.token_ids)-3):-1])
        text = (before + raw).decode('utf8', 'ignore')[
            len(before.decode('utf8', 'ignore')):]
        raw = before + raw
    single_byte = len(prefix.token_bytes[-1]) == 1
    if single_byte and raw.endswith('贝'.encode()[:2]):
        return None, -5.0
    if single_byte and raw.endswith('貝'.encode()[:2]):
        return None, -2.8
    value = lexical(text)
    if value:
        return None, value
    current, prev = unaccent(text), unaccent(previous)
    if not text or text[0].isspace():
        return None, 0.0
    if current in ('ui', 'uy') and prev.endswith(('g', 'k', 'c', 'd', 'h')):
        value = -0.8
    elif prev.endswith(('gu', 'qu')):
        if text in ('i', 'y'):
            value = -3.5
        elif current in ('ic', 'ig'):
            value = -2.2
        elif current in ('u', 'ue', 'ux', 'e', 'ai'):
            value = -0.9
    elif prev.strip() in ('g', 'k') and current in ('ue', 'uz', 'ual'):
        value = -0.8
    elif (text == 'i' and prev.endswith(('cu', 'ku')) and
          previous[-1].lower() != unaccent(previous[-1])):
        value = -5.5
    elif text == 'y' and previous.endswith(('á', 'à', 'ù', 'ú')):
        value = -2.2
    return None, value

"""A local line-boundary signal, strongest at chat and tool-turn endings.

Bare newlines differ from punctuation already fused with a newline.  Their
negative value is larger after symbols, padding, and code-introducing words.
Ordinary text is near zero. Two formatting exceptions are repeated middle
dots and the colon of a document-initial "Title:" header.
"""
import unicodedata

READS = ()

# Standalone statement/block introductions, rather than completed prose.
CONTINUATIONS = {'else', 'return', 'then', 'begin', 'select'}


def bare_break(previous, before, double):
    p = previous.strip()
    if previous == '<|im_end|>':
        if before == '</tool_call>':
            return -1.84
        if before == '</tool_response>':
            return -1.18
        if before.rstrip().endswith(('.', '。')):
            return -0.35
        return -0.50 if before.rstrip().endswith(('?', '？', '!')) else -0.62
    if p in {'assistant', 'user', 'system'}:
        return 0.11 if p == 'assistant' else 0.03
    if previous == '<tool_call>':
        return -0.22
    if previous == '<tool_response>':
        return -0.12
    if p.startswith('<') and p.endswith('>'):
        return 0.0
    if previous and previous.isspace():
        if '\n' in previous or '\r' in previous:
            return -0.5 * previous.count('\n')
        return -min(4.5, 0.11 * len(previous) +
                    (1.5 + 1.3 * previous.count('\xa0')
                     if '\xa0' in previous else 0.0))
    if not p:
        return 0.0
    if p.lower() in CONTINUATIONS:
        return -0.5 if double else -1.3
    if p.startswith('@') and p[1:].isalpha():
        return -0.8
    if p.isnumeric() and not p.isdecimal():
        return -0.7
    if p.isdecimal():
        return 0.02 if double else -0.17
    categories = [unicodedata.category(c) for c in p]
    if all(c[0] in 'PS' for c in categories):
        if not p.isascii():
            if categories[-1] in {'Pe', 'Pf', 'Pi'}:
                return -1.8
            if p[-1] in '、，':
                return -2.5
            return -0.9 if categories[-1] == 'So' else -1.3
        if p[-1] == '$':
            return -1.55
        if p[-1] == '^':
            return -1.4 if double else -2.5
        if categories[-1] == 'Pd':
            return -1.1
        if categories[-1] in {'Po', 'Pc'}:
            return -1.8 if double else -2.6
        return -0.9 if double else -2.0
    if not p.isascii():
        if all('HIRAGANA' in unicodedata.name(c, '') for c in p):
            return -0.58
        return -0.06
    if p.isupper():
        return 0.0 if double else -0.19
    if p.isalpha():
        return 0.07 if double else 0.0
    return 0.0 if double else -0.10


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = before = ''
    else:
        _, previous, before = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token.strip()) > 1 and set(token.strip()) == {'·'}:
        value = -1.23
    elif token == ':' and previous == 'Title' and before == '':
        value = 7.39
    elif token in {'\n', '\r\n', '\n\n', '\n\n\n'}:
        value = bare_break(previous, before, token.count('\n') > 1)
    elif '\n' in token:
        mark = token.rstrip('\r\n').strip()
        if mark in {')', ']', '/', ':'}:
            value = 0.06
        elif mark in {'.', '。'}:
            value = 0.02
        elif mark == '{':
            value = -0.05
        elif mark == '?':
            value = -0.05
    return (doc, token, previous), value

programs.haiku:
"""layers.1.mlp.down_proj:152, a line-break detector (negative) with one document-opener spike.

What it does, in plain terms. The component is almost silent on ordinary text. Its big
values come from a standalone line-break token ("\\n") that follows something other than an
ordinary word:
  - a line break right after the end of a tool call or tool response (the <|im_end|> that
    closes such a turn) is strongly negative (about -1.9 and -1.2);
  - a line break after other turn ends (<|im_end|> after plain text) is mildly negative (-0.45);
  - a line break after a symbol or punctuation mark (CJK or Unicode punctuation, quotes,
    '$$', '===', '^' and so on) is strongly negative (-1.5);
  - a line break after a run of whitespace (blank indentation) is very negative (-3.5);
  - a line break after a code keyword that opens a continuation (else, then, return,
    @Override) is negative (-1.2);
  - a line break after a digit is slightly negative (-0.2);
  - a line break after a letter is about zero.
Two more rules: the first token of each document is slightly negative (-0.15), and a colon
that is the second token of a document after the word "Title" is a large positive spike (+7.4).
Everything else predicts 0. Values are the group means observed on training text.
"""

READS = ()


def step(carry, prefix, upstream):
    # First token of a document (a row start, or a new document after <|endoftext|>).
    if len(prefix) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, -0.15
    # "Title:" opening a document: a fixed large spike on the colon.
    opens_doc = len(prefix) == 2 or prefix.document_ids[-3] != prefix.document_ids[-2]
    if opens_doc and prefix.token_strings[-2] == "Title" and prefix.token_strings[-1] == ":":
        return None, 7.4
    if prefix.token_strings[-1] != "\n":
        return carry, 0.0
    prev = prefix.token_strings[-2]
    last = prev[-1:]
    if prev == "<|im_end|>":
        before = prefix.token_strings[-3] if len(prefix) > 2 else ""
        if before == "</tool_call>":
            value = -1.85
        elif before == "</tool_response>":
            value = -1.2
        else:
            value = -0.45
    elif prev.startswith(("<|", "</", "<tool")):
        value = -0.2
    elif prev.strip() == "" and prev != "":
        value = -3.5
    elif last.isdigit():
        value = -0.2
    elif last.isalpha() or last == "":
        value = -1.2 if prev in ("else", "then", "return", "@Override") else 0.0
    else:
        value = -1.5
    return carry, value

programs.sol:
"""Approximate a document-initial lexical and formatting response.

Training activations concentrated at document starts and initial uniform runs.
Use coarse word/format classes on the first token and its exact repetitions;
replace the remaining context-dependent activity with a small background.
Unlisted words use spelling properties, not a token-identity table.
"""
import calendar
from functools import lru_cache
import regex

READS = ()
MONTHS = {s.lower() for s in (*calendar.month_name[1:],
                             *calendar.month_abbr[1:])}
PREPOSITIONS = {
    'to': -2.5, 'of': -1.1, 'at': -3.7,
    'about': -5.1, 'into': -1.7, 'from': -1.4,
}
GRAMMAR = (
    ('i you he she it we they me him us them my your his her its our their', 1.6),
    ('this that these those', 1.2),
    ('be been being', 2.1),
    ('has', -5.5),
    ('is are was were have had can could may might will would shall should must', -.1),
    ('and or but if then because so while', .5),
)
GRAMMAR = {w: v for words, v in GRAMMAR for w in words.split()}


@lru_cache(maxsize=30000)
def initial_value(s):
    w = s.strip()
    lo = w.lower()
    space = s.startswith(' ')
    if s.startswith('<|'):
        return .48
    if w.isascii() and w.isdigit():
        return 4.0
    if not w:
        if '\r' in s and '\n' in s:
            return -7.5
        if '\t' in s and '\n' in s:
            return -8.0
        if '\n' in s:
            return -2.9 if s.count('\n') == 1 else -1.7
        if s == '\r':
            return -.65
        if set(s) == {'\t'}:
            return -2.4 - min(2, len(s)-1)
        if set(s) == {'\u00a0'}:
            return -2.3 - .8 * min(5, len(s)-1)
        return .22
    if '\n' in s or '\r' in s:
        if any(c in s for c in '{};[]'):
            return -9.0
        return -4.7
    if lo in MONTHS and w != 'may':
        return -8.8
    if lo in ('page', 'chapter', 'section', 'part', 'level', 'version', 'form', 'case'):
        return -6.7
    if lo in ('how', 'what'):
        return 9.7 if w[0].isupper() else 5.4
    if lo in ('why', 'when'):
        return 5.0
    if lo in ('who', 'which', 'where'):
        return 2.1
    if not space:
        if w in ('package', 'namespace'):
            return 14.2 if w == 'package' else 10.8
        if w in ('class', 'def', 'using', 'from', 'int', 'string', 'var', 'void'):
            return 7.0
        if w in ('import', 'const', 'function', 'export'):
            return 3.6
    if lo in ('a', 'an', 'the'):
        if s == 'A':
            return .85
        return 4.2 if space else 2.86
    if lo in GRAMMAR:
        return GRAMMAR[lo]
    if lo in PREPOSITIONS:
        return PREPOSITIONS[lo]
    if lo in ('in', 'on', 'as', 'for', 'by', 'with'):
        return 1.7 if space else 2.7
    if len(w) > 1 and set(w) == {'·'}:
        return -2.8  # Middle-dot leaders.
    if set(w) == {'#'}:
        return 6.8 if len(w) <= 2 and not space else 2.0
    if w in ('//', '/*', '/**'):
        return 2.8
    if w in ('=', '+', '=>'):
        return -2.4
    if w in (')', ']', '}'):
        return 1.5
    if regex.fullmatch(r'[\p{P}\p{S}]+', w):
        return -.4
    # Small spelling-based fallback for words outside the named classes.
    ascii_word = w.isascii() and w.isalpha()
    value = .34
    if ascii_word and len(w) == 1:
        value += 1.26
    if lo in ('than', 'over', 'between', 'least', 'most', 'top', 'bottom', 'since'):
        value -= 5.2
    if regex.fullmatch(r'\p{Script=Han}+', w):
        value -= 1.46
    if ascii_word and len(w) == 3:
        value -= .86
    if ascii_word and len(w) > 1 and w.isupper():
        value -= 1.54
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        first, uniform = token, True
    else:
        _, first, uniform = carry
        uniform = uniform and token == first
    value = initial_value(prefix.token_strings[-1]) if uniform else .004
    return (doc, first, uniform), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:155, explained as a "unit of measure right after a number" detector.

What it does, in plain terms:
- It fires on the abbreviation of a unit of measurement (s, ms, min, h, Hz, m, km, mm, nm,
  g, mg, kg, lb, oz, ft, mi, L, ml, gal, tsp, V, W, kW, GW, dB, Pa, mol, ...) when it follows
  a number, with at most two words in between (e.g. "10 µ s").
- Strength depends on the gap: a space between number and unit ("20 min", "5 km") gives a
  strong response, a unit stuck to the digit ("10m") a weak one, and a no-break space
  ("65 s", the typographic style of tables) the strongest.
- Negative on "per" in unit phrases ("grams per ..."), and on "metric" in "t/metric tsp".
- Negative on runs of middle dots ("····"), a fixed value in filler text.
- Everything else predicts 0. Spelled-out units ("feet", "miles", "days") and ambiguous capital
  letters (A, K, M, J) are left out: they barely move the component.
"""
import re

READS = ()

UNITS = {
    "s", "ms", "ns", "sec", "min", "h", "Hz", "kHz", "MHz", "GHz", "m", "cm", "mm", "km", "nm",
    "g", "mg", "kg", "lb", "oz", "ft", "mi", "L", "mL", "ml", "gal", "tsp", "tbsp", "V", "mV",
    "kV", "mA", "W", "kW", "MW", "GW", "mM", "dB", "Pa", "kPa", "N", "kJ", "kcal", "mol", "MB",
    "GB", "Mb", "pc", "ha", "/s", "/m", "/min", "/h", "/d", "/L",
}
SPACED, ATTACHED, NBSP = 2.0, 0.6, 4.0
PER, METRIC, DOTS = -1.0, -1.5, -1.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip()
    # carry: (words since the last number, separator after the number, after "per" or "/")
    if carry is None or (len(prefix) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]):
        gap, sep, after_per = 99, "none", False
    else:
        gap, sep, after_per = carry
    value = 0.0
    if word and set(word) == {"·"}:
        value = DOTS
    elif word in UNITS and gap <= 2:
        if tok.startswith(" ") or sep == "space":
            value = SPACED
        elif sep == "nbsp":
            value = NBSP
        else:
            value = ATTACHED
    elif word == "per" and gap <= 3:
        value = PER
    elif word in ("metric", "etric") and (after_per or gap <= 2):
        value = METRIC
    # update the state for the next token
    if re.search(r"\d", tok):
        new = (0, "none", False)
    elif word == "":
        if "\xa0" in tok:
            new = (gap, "nbsp", after_per)
        elif " " in tok:
            new = (gap, "space", after_per)
        else:
            new = (99, "none", False)
    else:
        new = (gap + 1, "none", word in ("per", "/"))
    return new, value

programs.sol:
"""Words pointing to a thing: chiefly English 'that' and 'those'.

Estimate a negative response, weak for clause-linking/relative 'that' and
strong for demonstrative 'that': after prepositions, contrasts, or breaks.
The preceding word and punctuation provide a deliberately local grammar cue.
Also capture the sharp colon response in a document-initial Title: label.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

PREPOSITIONS = set('''about above across after against along among around as at
before behind below beneath beside between beyond by despite down during except
for from in inside into like near of off on onto opposite out outside over past
through throughout to toward towards under underneath unlike until up upon via
with within without than'''.split())
AUXILIARIES = set('''am is are was were be been being have has had can could
will would shall should may might must'''.split())
DISCOURSE_MARKERS = set('''well wait yes no okay ok yep yeah right now then
however sometimes actually instead unfortunately fortunately indeed'''.split())
THOUGHT_VERBS = set('think believe suppose assume imagine hope expect feel'.split())
ACTION_VERBS = set('''do make put get take give use fix change reduce convert
implement calculate figure play pop publish prevent present repeat
choose select remove add follow build connect compute set sell bake enhance
tie address receive include apply translate let call introduce buy eat
drink'''.split())
VERIFY_VERBS = {'check', 'verify', 'test', 'try'}
CLAUSE_VERBS = set('''say state report tell announce write claim argue conclude
indicate suggest show reveal demonstrate observe find know understand mean
ensure require imply prove note notice confirm see learn agree emphasize
propose mention seem need rule perceive intend notify draw recall describe
remember forget accept reject'''.split())

# Distal demonstratives in several other languages.  These are word forms,
# not token IDs; reconstructing a word also handles split endings like qu+ella.
SPANISH_DISTAL = set("""ese esa esos esas aquel aquella aquellos aquellas
                         aquello""".split())
ITALIAN_DISTAL = {'quel', 'quello', 'quella', 'quelli', 'quelle'}
PORTUGUESE_DISTAL = set("""esse essa esses essas isso aquele aquela aqueles
                            aquelas aquilo""".split())


def translated_value(token, before):
    if token.strip() == 'その':
        return -1.7
    if token.strip() == 'それ':
        return -2.4
    if token.strip() == '그':
        return -2.7
    if not token or not token[-1].isalpha():
        return 0.0
    match = re.search(r'[^\W\d_]+$', before + token)
    raw = match.group() if match else ''
    # Do not read a partly spelled capitalized name as a demonstrative.
    if raw[:1].isupper() and before[-1:].isalpha() and not token[:1].isspace():
        return 0.0
    word = raw.lower()
    if word in SPANISH_DISTAL:
        return -4.8
    if word == 'eso':
        return -1.5
    if word in ITALIAN_DISTAL:
        return -3.7
    if word in PORTUGUESE_DISTAL:
        return -1.4
    if word == 'dat':                 # Dutch
        return -1.4
    if word == 'det':                 # Scandinavian neuter demonstrative
        return -0.8
    if word == 'das':                 # German neuter article/demonstrative
        return -0.4
    return 0.0


@lru_cache(maxsize=4096)
def verb_kind(word):
    bases = set(wordnet.base_forms(word)) | {word}
    if bases & THOUGHT_VERBS:
        return 'thought'
    if bases & CLAUSE_VERBS:
        return 'clause'
    if bases & VERIFY_VERBS:
        return 'verify'
    if bases & ACTION_VERBS:
        return 'action'
    return 'other'

def that_value(token, before):
    word = token.strip()
    if word[0].isupper():
        return -5.5 if token[:1].isspace() else -3.9
    match = re.search(r'([A-Za-z]+|[^\w\s])\s*$', before)
    previous = match.group(1) if match else ''
    low = previous.lower()
    if low == 'out' and re.search(
        r'\b(?:turn(?:s|ed|ing)?|point(?:s|ed|ing)?|find|found) out\s*$',
        before.lower(),
    ):
        return -0.6
    if low == 'given':
        return -0.5
    if low == 'at':
        return -8.5
    if low in PREPOSITIONS:
        return -6.2
    if low == 'if':
        return -9.2
    if low in {'but', 'though', 'although', 'because', 'whether', 'since',
               'when', 'while', 'where', 'once', 'unless'}:
        return -7.8 if previous[:1].isupper() else -6.5
    if low in {'and', 'or', 'yet', 'also'}:
        return -3.3
    if previous == 'so':
        return -2.3
    if low == 'not':
        return -2.0
    if previous == 'So' or low in DISCOURSE_MARKERS or low in {
        'do', 'did', 'does', 'done', 'again', 'hence', 'that',
        'maybe', 'perhaps', 'probably', 'surely', 'certainly', 'possibly',
        'thus', 'therefore', 'whatever', 'how',
    }:
        return -5.7
    if low in {'even', 'just', 'only', 'exactly', 'all', 'both', 'what'}:
        return -4.2
    if previous == ';':
        return -2.7
    if previous in {'.', '!', '?'}:
        if re.search(r'\b(?:Jr|Sr|Dr|Mr|Mrs|Ms)\.\s*$', before):
            return -0.5
        return -5.7
    if previous == ',':
        words = re.findall(r'[A-Za-z]+', before.lower())
        if words and words[-1] in DISCOURSE_MARKERS:
            return -8.0
    if previous in {',', ':', '"', '“', '”'}:
        return -3.1
    if low in AUXILIARIES:
        if previous[:1].isupper() or re.search(
            r'\b(?:why|how|what) \w+\s*$', before.lower()
        ):
            return -6.5
        return -1.0
    kind = verb_kind(low)
    if kind == 'thought':
        return -1.4
    if kind == 'clause':
        return -0.7
    if kind == 'verify' and previous[:1].isupper() and low != 'try':
        return -0.4
    if kind in {'action', 'verify'}:
        words = re.findall(r'[A-Za-z]+', before.lower())
        prior = words[-2] if len(words) > 1 else ''
        if prior in {'a', 'an', 'the', 'my', 'your', 'our', 'their',
                     'his', 'her', 'this', 'these', 'those', 'that', 'other',
                     'any', 'some', 'many', 'several', 'few', 'more',
                     'additional', 'another'}:
            return -0.2
        return -2.4 if kind == 'verify' else -4.6
    pos = wordnet.parts_of_speech(low)
    if pos == {'verb'}:
        return -1.7
    if pos == {'adjective', 'verb'}:
        return -0.8
    return -0.2

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    if token == ':' and before == 'Title':
        value = -12.1
    elif word.lower() in {'that', 'thats'}:
        value = that_value(token, before)
    elif word.lower() == 'those':
        value = -2.7
    else:
        value = translated_value(token, before)
    return (doc, (before + token)[-160:]), value

programs.haiku:
"""Layer-1 MLP down-projection component 156: a negative "that" detector.

It is silent (about 0) almost everywhere, but on the word "that" (and "those")
it goes strongly negative when "that" is a demonstrative pointing back at
something ("at that point", "But that is", "Wait, that's"), moderately negative
when "that" opens a clause after a verb or a conjunction ("I think that", "and
that"), and near zero for a relative "that" after a noun ("the music that").

The program reads only the previous word, sorted into a few tiers:
  - after punctuation, a preposition, or a sentence-opening word: about -5;
  - after ",", "and", "so": about -3;
  - after a verb of saying/thinking/showing, or "is": about -1;
  - after a noun like "fact" or "such", after a closing bracket or quote, or at the
    start of a document: about 0;
  - after anything else (mostly verbs and nouns): about -0.5.
"those" is about -2.5 wherever it comes. Everything that is not "that"/"those" predicts 0.
"""

READS = ()

PUNCTUATION = set(".!?;:…\n“")
CLOSERS = set(")]\"”")
PREPOSITIONS = set(
    "in on at to for of from by with into about after before during until since "
    "like between through than within among over under as all do does did make use "
    "get keep break lay up out off".split()
)
OPENERS = set(
    "but if when because maybe then or what while where however also wait oh "
    "yes no well ah now".split()
)
WEAK = {",", "and", "so"}
SAYING = set(
    "think thought know knew say said says saying show shows showed shown found find "
    "believe believed suggest suggests suggested indicate indicates indicated mean "
    "means meant assume assuming see seen realize realized understand hope sure state "
    "states stated prove conclude concluded estimate reveals revealed demonstrate argue "
    "claims remember suppose is was are were ensure notes note noted reports confirm".split()
)
NOUNISH = {"such", "fact", "note", "meaning", "something", "problem", "point"}


def previous_word(prefix):
    """The word before the newest token, or '' at the start of a document."""
    t = prefix.position
    if t == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[-2].strip().lower()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word not in ("that", "those"):
        return carry, 0.0
    prev = previous_word(prefix)
    if word == "those":
        return carry, -2.5
    if prev == "":
        value = 0.0
    elif prev in PUNCTUATION or prev in PREPOSITIONS or prev in OPENERS:
        value = -5.0
    elif prev in WEAK:
        value = -3.0
    elif prev in SAYING:
        value = -1.0
    elif prev in NOUNISH or prev in CLOSERS:
        value = 0.0
    else:
        value = -0.5
    return carry, value

programs.sol:
"""Approximate a negative response to the consonant spelling 'st'.

Short pieces and letters continuing an st-containing word get larger negative
values than familiar whole words. Transliteration covers other alphabets;
Japanese su and Korean seu are treated as the s in loanword clusters. The
signal fades as more letters follow st. Two explicit formatting exceptions
are bare assistant labels and a document-initial Title: header.
"""

import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=32768)
def spelling(text):
    if '<|' in text or text.startswith(('<tool', '</tool')):
        return '', '', '', ''
    roman = anyascii(text.replace('ス', 's').replace('스', 's')).lower()
    words = re.findall('[a-z]+', roman)
    cluster = next((w for w in reversed(words) if 'st' in w), '')
    head = re.match('[a-z]+', roman)
    tail = re.search('[a-z]+$', roman)
    return roman, cluster, head.group() if head else '', tail.group() if tail else ''


def current_piece(piece, text):
    """Short fragments are strongest; common long words are weaker."""
    length = len(piece)
    frequency = zipf_frequency(piece, 'en')
    if length == 2:
        return -1.32 if text[:1].isspace() else -1.60
    if length == 3:
        return -1.53 if frequency <= 3.25 else -0.96
    if frequency <= 3.96:
        return -1.08 if length <= 5 else -0.42
    return -0.45 if piece.startswith('st') else -0.24


def continuation(suffix, text, previous):
    """The remaining signal depends on letters already following st."""
    if suffix <= 1:
        if len(text) <= 2:
            return -1.92 if suffix == 0 else -1.14
        return -0.98 if zipf_frequency(text.strip(), 'en') <= 4.52 else -0.14
    if suffix <= 3:
        return -0.62 if len(text) <= 2 else -0.34
    return -0.42 if previous[:1].isspace() else -0.08


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, last_letter, suffix = 0, '', '', None
    else:
        _, position, previous, last_letter, suffix = carry
    text = prefix.token_strings[-1]
    roman, piece, head, tail = spelling(text)
    joins_word = bool(head and last_letter)
    crosses_st = joins_word and last_letter == 's' and head.startswith('t')

    value = -0.003
    if piece:
        value = current_piece(piece, text)
    elif crosses_st:
        value = -3.10 if any(ord(c) > 127 for c in text) else -0.81
    elif joins_word and suffix is not None:
        value = continuation(suffix, text, previous)

    if text == 'assistant':
        value = -1.85 if position == 0 else -3.15
    if position == 1 and previous == 'Title' and text == ':':
        value = -11.65

    # Only the final word fragment can connect to the next token.
    next_suffix = None
    if tail:
        if 'st' in tail:
            next_suffix = len(tail) - tail.rfind('st') - 2
        elif roman == tail and joins_word:
            if crosses_st:
                next_suffix = len(tail) - 1
            elif suffix is not None:
                next_suffix = suffix + len(tail)
    next_letter = tail[-1:] if tail else ''
    state = (doc, position + 1, text, next_letter, next_suffix)
    return state, value

"""Local grammatical cues, especially selected counts and marked participles.

Count words are strongest after demonstratives or ordering words. Articles
respond to partitives, and participles to newly, temporal/frequency adverbs,
and split un-/mis-/self- prefixes. Smaller rules cover Romance articles,
Chinese classifiers/verbal markers, Japanese no, and negative connective cues.
These are surface heuristics, not a parser. Weights are rounded training-case
means, not token-ID lookups. A 100-character buffer resets per document.
"""
import re
import unicodedata
from functools import lru_cache

import cedict
import inflect
import regex
import wordnet

READS = ()
COUNTS = {inflect.engine().number_to_words(i) for i in range(2, 21)}
ORDERING = {'first', 'last', 'next', 'previous', 'past', 'following',
            'remaining', 'top', 'bottom', 'final', 'initial', 'latter', 'former'}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
PARTITIVES = {'one', 'each', 'either', 'neither', 'any', 'many', 'some',
              'most', 'all', 'both', 'none', 'half', 'several',
              'few', 'more', 'much', 'which'}
IRREGULAR_PARTICIPLES = {
    'known', 'given', 'seen', 'shown', 'found', 'built', 'born', 'written',
    'taken', 'chosen', 'broken', 'made', 'done', 'grown', 'drawn', 'driven',
    'held', 'left', 'lost', 'set', 'put', 'read',
}
AUXILIARIES = {'is', 'are', 'was', 'were', 'be', 'been', 'being',
               'has', 'have', 'had', 'get', 'got'}
# Columns: two, three, four-to-twenty, few/several.
COUNT_STRENGTH = {
    'demonstrative': (3.73, 2.95, 1.88, 0.0),
    'other': (4.46, 4.14, 2.5, 0.0),
    'ordered': (3.52, 2.6, 1.41, 1.63),
    'quantified': (2.46, 2.91, 1.88, 0.91),
    'definite': (1.42, 1.27, 1.01, 0.34),
    'ordinary': (0.05, 0.17, 0.05, 0.04),
}
# Columns: separating space, numeral prefix 2-4, numeral prefix 5-20.
NUMERAL_STRENGTH = {
    'ordered': (1.36, 1.57, 1.34),
    'quantified': (1.41, 1.64, 1.93),
    'definite': (0.22, 0.46, 0.47),
}


@lru_cache(maxsize=20000)
def past_verb(word):
    return any(base != word and 'verb' in wordnet.parts_of_speech(base)
               for base in wordnet.base_forms(word))


@lru_cache(maxsize=10000)
def classifier(ch):
    return any('classifier' in g.lower() for g in cedict.glosses(ch))


def predict(previous, token):
    s = token.strip().lower()
    words = re.findall(r"[a-z]+(?:'[a-z]+)?", previous.lower())
    p = words[-1] if words else ''
    q = words[-2] if len(words) > 1 else ''
    if not re.search(r'[a-z]\s*$', previous.lower()):
        if token != ' ' and not (s.isascii() and s.isdigit()):
            p = q = ''
    if s in COUNTS or s in {'few', 'several'}:
        size = 0 if s == 'two' else 1 if s == 'three' else 2
        if s in {'few', 'several'}:
            size = 3
        context = 'ordinary'
        if p in {'these', 'those'}:
            context = 'demonstrative'
        elif p == 'other':
            context = 'other'
        elif p in ORDERING:
            context = 'ordered'
        elif p in {'all', 'any', 'both', 'every', 'each'}:
            context = 'quantified'
        elif p == 'the' or p in POSSESSIVES or p in {'no', 'another', 'same'}:
            context = 'definite'
        return COUNT_STRENGTH[context][size]
    if token == ' ' or (s.isascii() and s.isdigit()):
        if token == ' ':
            m = re.search(r'([a-z]+)$', previous.lower())
            size = 0
        else:
            m = re.search(r'([a-z]+) +([0-9]*)$', previous.lower())
            if m:
                digits = m.group(2) + s
                n = int(digits) if len(digits) < 4 else 1000
                if n < 2 or n > 20:
                    m = None
            size = 1 if m and n <= 4 else 2
        if m:
            p = m.group(1)
            context = ('ordered' if p in ORDERING or p == 'other' else
                       'quantified' if p in {'these', 'those', 'all', 'any'} else
                       'definite' if p == 'the' else None)
            if context:
                return NUMERAL_STRENGTH[context][size]
    if s == 'the':
        if p == 'what':
            return -0.94
        if p == 'of':
            if q in {'rest', 'remainder'}:
                return 2.96
            if q in PARTITIVES or q in COUNTS:
                return (1.59 if q == 'one' else
                        2.16 if q == 'most' else
                        1.54)
            return 0.12
        if p in {'all', 'both'}:
            return 0.61
        if p in {'between', 'among'}:
            return 0.1
        if p in {'are', 'were'}:
            return 0.26
        return -0.01
    if s in {'a', 'an'} and p in {'what', 'each'}:
        return -0.94
    if s in POSSESSIVES or s in {'these', 'those', 'other'}:
        if p in {'all', 'both'}:
            return 0.45
        if p == 'of' and q in PARTITIVES:
            return 0.66
    if s in {'os', 'as', 'los', 'las', 'les', 'le', 'i'} and p in {
            'todos', 'todas', 'todo', 'toda', 'tous', 'toutes', 'tutti', 'tutte'}:
        return 2.83 if s in {'las', 'os', 'as'} else 1.52
    if token in {"'s", '’s'} and p in {'today', 'yesterday', 'tomorrow'}:
        return 2.25
    if token == 'の':
        return 0.25
    if regex.match(r'\p{Script=Han}', token):
        ch = token[0]
        number = unicodedata.numeric(ch, None) is not None or ch in '两兩几幾'
        if previous.endswith(('这', '這', '那', '此')):
            return 1.15 if number or classifier(ch) else 0.
        if (previous and unicodedata.numeric(previous[-1], None) is not None
                and classifier(ch)):
            return 0.13
    if (previous.endswith(('所', '被', '已', '未'))
            and regex.fullmatch(r'\p{Script=Han}+', token)):
        return 0.78 if len(token) == 1 else 0.41
    if s == 'most':
        return -0.43 if p == 'the' or p in POSSESSIVES else -0.12
    if s in {'to', 'in', 'of', 'at', 'with'} and (
            p.endswith('est') or p in {'more', 'less', 'possible', 'able'}):
        return -0.18
    match = re.search(r'[a-z-]+$', previous.lower())
    fragment = match.group() if match and not token[:1].isspace() else ''
    word = fragment + s
    if word.endswith('ed') or word in IRREGULAR_PARTICIPLES:
        modifier = q if fragment else p
        before = words[-3] if fragment and len(words) > 2 else q
        auxiliary = before in AUXILIARIES
        if modifier == 'newly':
            return 3.57
        if modifier in {'recently', 'currently', 'previously', 'formerly',
                        'freshly', 'permanently', 'retrospectively', 'already'}:
            return 0.25 if auxiliary else 0.66
        if modifier in {'frequently', 'commonly', 'widely', 'rarely', 'often',
                        'regularly', 'generally', 'usually', 'extensively'}:
            return 0.01 if auxiliary else 0.61
        if word.startswith(('un', 'mis')) or 'self-' in word:
            return 0.82 if fragment else 0.01
        if modifier in {'the', 'a', 'an', 'these', 'those', 'top'}:
            return 0.4 if past_verb(word) else 0.08
        if fragment:
            return 0.13
        return 0.01
    return 0.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(previous, token)
    return (doc, (previous + token)[-100:]), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:159 -- a "question about *me*" detector.

Plain-language reading: this component is positive when the text is asking a question
about the writer ("How do I renew my license?", "Can I tile myself?"), strongest on the
first-person subject "I" placed right after a question auxiliary (do / can / should ...),
weaker on "my"/"me" inside such a question and on the question's opening word and question
mark. It is negative on "you"/"your" inside a question, most of all "What is your ...".
Everything else is close to 0.

The program tracks, token by token, whether the current sentence began with a question
opener (a wh-word or an auxiliary such as Do, Can, Are) and is still open (no "?" or newline
yet). Predictions are fitted weights, rounded, in the component's activation units.
"""
READS = ()

QUESTION_AUX = {"do", "does", "can", "could", "should", "would", "will", "shall", "may", "might"}
OPENERS = {"what", "how", "where", "when", "why", "who", "which", "are", "is", "am", "do",
           "does", "can", "could", "should", "would", "will", "have", "has"}
BOUNDARY_TOKENS = {".", "!", "?", "？", "\n", "<|endoftext|>"}
SECOND_PERSON = {"you", "your"}


def step(carry, prefix, upstream):
    # carry: (last word, at sentence start, inside an open question)
    last, at_start, in_question = carry if carry else ("", True, False)
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        last, at_start, in_question = "", True, False
    value = 0.0
    if word == "i" and last in QUESTION_AUX:
        value = 2.7  # subject "I" after an auxiliary: "Do I", "How can I", "Should I"
    elif word == "i" and last in ("if", "when"):
        value = 0.2
    elif word == "am" and last == "i":
        value = 0.5  # "I am" self-introductions
    elif word in ("my", "me") and in_question:
        value = 1.3
    elif word in ("your", "you") and last in ("is", "are", "be", "'s") and in_question:
        value = -1.9  # "What is your ..."
    elif word in SECOND_PERSON and (in_question or last in QUESTION_AUX):
        value = -0.4
    elif at_start and word in OPENERS:
        value = 0.4  # the question's opening word
    elif token.strip() in ("?", "？"):
        value = 0.3  # the question mark
    elif token.strip() in ("嗎", "吗"):
        value = 1.5  # Chinese question particles
    elif token.strip() and set(token.strip()) == {"·"}:
        value = 0.55  # runs of dots
    if at_start and word in OPENERS:
        in_question = True
    if word:
        at_start = False
    if token.strip() in ("?", "？") or "\n" in token:
        in_question = False
    if token in BOUNDARY_TOKENS or token.strip() in (".", "!", "?", "？") or "\n" in token:
        at_start = True
    if word:
        last = word
    return (last, at_start, in_question), value

programs.sol:
"""Approximate the negative response to Slavic oblique-plural noun forms.

The main cues are Russian -ов and other case endings, Polish -ów,
and Czech -ů. Word-frequency comparisons suggest Russian bare-stem
(genitive plural) nouns, while rejecting many adjective and verb stems.
Token boundaries and capitalization modulate the response. Arabic-script -ات
and runs of middle dots have separate responses. This is a heuristic,
not a full morphological parser; numbers were fitted on training text.
"""
READS = ()
import regex as re
from functools import lru_cache
from wordfreq import zipf_frequency

@lru_cache(maxsize=100000)
def bare_plural_kind(s):
    # Bare stems of Russian -а or neuter -о nouns. Contrast their
    # ordinary inflections with -ов, the masculine plural ending.
    if len(s)<3 or not re.fullmatch('[а-яё]+',s):
        return None
    if s[-1] not in 'бвгджзклмнпрстфхцчшщ':
        return None
    # Zipf scores increase with word frequency.
    z = lambda x: zipf_frequency(x, 'ru')
    f=z(s)
    a=z(s+'а')
    plural=z(s+('и' if s[-1] in 'гкхжчшщ' else 'ы'))
    adjective=max(z(s+'ый'),z(s+'ий'),z(s+'ые'),z(s+'ие'))
    if f>=3.5 and z(s+'ов')<2.0 and s not in {'наш','ваш','рад'}:
        if adjective<2.5 and min(a,plural)>=3.2 and min(a,plural)-f>=-0.6:
            return 'feminine'
        # Past-tense -л/-ла/-ло are verb forms, not a noun paradigm.
        neuter_forms = min(z(s+'о'), a)
        if (not s.endswith('л')
                and neuter_forms > max(3.2, adjective+0.5)
                and neuter_forms-f >= -1.5):
            return 'neuter'
    # Vowel insertion: кнопка -> кнопок, ножка -> ножек.
    if s.endswith(('ок','ек')) and f>=1.2:
        stem=s[:-2]
        if min(z(stem+'ка'),z(stem+'ки'))>=2.1 and z(stem+'ков')<2:
            return 'fleeting_vowel'
    return None


# Bare-stem response, then the extra response at a word boundary.
BARE_RESPONSES = {
    'feminine': (-0.257, -0.351),
    'neuter': (-0.442, -1.252),
    'fleeting_vowel': (1.047, 1.665),
}

POSSESSIVES = {
    'своей', 'твоей', 'моей',
    'вашей', 'нашей', 'всей',
}
IRREGULAR_PLURALS = {
    'лет', 'людей', 'детей', 'дней',
    'граждан', 'времен', 'времён',
    'имён', 'имен', 'семян',
    'племён', 'племен', 'крестьян',
}


def predict(token, before, word):
    s = token.strip().lower()
    w = word.lower()
    value = 0.00145
    separate = not token[:1].isspace()
    if re.fullmatch('[А-Яа-яЁё]+',token.strip()):
        value -= 0.012
        # Genitive, locative, instrumental and dative plural endings.
        if len(w)>3:
            if w.endswith('ов'):
                value += 0.500
                if s=='ов':
                    value -= 2.740
                if separate and s!='ов':
                    value -= 1.391
                if word[0].isupper():
                    value += 1.016
                if zipf_frequency(w,'ru')>2.0:
                    value -= 1.353
                if zipf_frequency(w+'ать','ru')>2.0:
                    value += 0.359
            elif w.endswith('ев'):
                value -= 0.801
            elif separate and w.endswith(('ах','ях')):
                value -= 2.486
            elif separate and w.endswith(('ами','ями')):
                value -= 1.315
            elif separate and w.endswith(('ам','ям')):
                value -= 1.109
            elif separate and w.endswith(
                    ('аний', 'ений', 'ствий', 'тий', 'ций')):
                value -= 3.773
            elif (separate and s=='ий' and
                  max(zipf_frequency(w[:-2]+'ие','ru'),
                      zipf_frequency(w[:-2]+'ия','ru')) > 2.1):
                value -= 1.484
            elif (w.endswith('ей') and not w.endswith(('шей','щей'))
                  and w not in POSSESSIVES):
                value -= 1.483
                if word[0].isupper():
                    value += 1.309
            elif w.endswith('ств'):
                value -= 0.793
        kind = bare_plural_kind(s)
        if kind:
            value += BARE_RESPONSES[kind][0]
            if not before or token[:1].isspace():
                value += BARE_RESPONSES[kind][1]
                if kind=='feminine':
                    value -= 2.102 * max(0.,zipf_frequency(s,'ru')-4.)
        if s.endswith(('ок','ек')) and bare_plural_kind(w)=='fleeting_vowel':
            value -= 2.421
        if s in IRREGULAR_PLURALS:
            if not before or token[:1].isspace():
                value -= 1.611
    if w.endswith('ات') and re.search('[\u0620-\u063f\u0641-\u064a]', s):
        value -= 0.692
        if s=='ات':
            value -= 1.401
    # West Slavic genitive plurals and oblique plural case suffixes.
    if re.fullmatch(r'\p{Latin}+',token.strip()):
        if s.endswith('ów'):
            value -= 4.242
        elif s.endswith('ů'):
            value -= 4.303
        elif separate and s.endswith(('ách','ích')):
            value -= 2.235
        elif (s.endswith('ach') and len(w)>4
              and zipf_frequency(w,'pl') > zipf_frequency(w,'en')):
            value -= 1.366
        elif s.endswith('ami'):
            value -= 1.082
        elif s.endswith('ov'):
            value -= 0.685
        elif s.endswith('ń'):
            value -= 1.827
        elif s.endswith(('nych','zych')):
            value -= 0.929
    if len(s)>1 and all(c=='·' for c in s):
        value -= 1.210
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    word = before
    token = prefix.token_strings[-1]
    for char in token:
        word = (word + char)[-60:] if char.isalpha() else ''
    return (doc, word), predict(token, before, word)

"""A spelling-based approximation of an early MLP feature.

The strongest responses concern the chunk 'ang': its left-hand spelling
changes the sign. Huang/huang-like spellings and emperor words are positive;
several other onsets and right-angle expressions are negative. This is not a
general meaning detector. There are also a few document-start calibrations;
otherwise small responses on ordinary tokens are left at zero.
"""
import regex as re
from functools import lru_cache
from pypinyin import lazy_pinyin

READS = ()


def ang_after(left):
    """Signed strength of a separate ang chunk, by its left-hand spelling."""
    if not left:
        return -0.2
    for endings, value in (
        (('ho', 'hu'), 7.5),
        ('ul', 5.5),
        (('nt', 'nd', 'str'), -5.0),
        (('th', 'gr', 'er'), -3.0),
        (('ch', 'sh', 'el', 'ur', 'am'), 0.0),
    ):
        if left.endswith(endings):
            return value
    for letters, value in (
        ('uo', 5.2),
        ('lwiy', 1.5),
        ('snp', -4.5),
        ('tdfzm', -2.7),
        ('bv', -0.3),
        ('h', 0.7),
        ('a', -0.2),
    ):
        if left[-1] in letters:
            return value
    return -1.2


@lru_cache(maxsize=2048)
def chinese_spelling(token):
    if re.fullmatch(r'\p{Script=Han}', token):
        return lazy_pinyin(token)[0]
    return ''


def predict(token, before, position):
    s = token.strip()
    low = s.lower()
    left_match = re.search(r'[a-z]+$', before.lower())
    left = left_match[0] if left_match else ''

    # The emperor / Huang association also occurs outside Roman lettering.
    if low in ('emperor', 'emperors', 'peror') or s == '皇帝':
        return 1.5
    if s == '皇':
        return 4.4
    reading = chinese_spelling(s)
    if reading == 'huang':
        return 1.2
    if reading == 'lang':
        return 0.7
    if s == '황':
        inside_word = re.search(r'\p{Script=Hangul}$', before)
        return 0.2 if inside_word else 7.0

    if low == 'langle' or s == '⟨':
        return -2.8 if low == 'langle' else -1.5
    if re.fullmatch(r'angle[ds]?', low.lstrip('-')):
        if re.search(r'\bright[ -]*$', before.lower()):
            return -5.3 if low.endswith('d') else -4.5
        if token.startswith('-') or before.endswith('-'):
            return -1.3
        if token[:1].isspace():
            return -0.15
        if left.endswith('quadr'):
            return -6.5
        if left in ('r', 'rect', 'tri', 'rotate', 'begin'):
            return 0.0
        return 0.6 * ang_after(left) - 0.4

    # Whole ang-syllable chunks are weaker than a separate ang continuation.
    onset = re.fullmatch(r'([a-z]{1,2})ang', low)
    if onset:
        start = onset[1]
        if start in ('hu', 'hw'):
            return 5.7
        if start == 'u':
            return 9.0 if left.endswith('h') else 5.5
        if start in ('l', 'w', 'i'):
            return 1.3
        if start == 'y':
            return 0.7 if s[:1].isupper() else 0.0
        if start == 's':
            return -3.1
        if start == 'p':
            return -2.5
        if start in ('m', 't', 'f', 'j'):
            return -1.4
        if start in ('r', 'g'):
            return -0.5
        return 0.0

    if low.startswith('ang'):
        if token[:1].isspace() or s[:1].isupper() and not s.isupper():
            return -0.4
        strength = ang_after(left)
        if low == 'ang':
            return strength
        if low.startswith(('angan', 'angkan')):
            return 0.8 * strength - 0.2
        if low.startswith(('ango', 'angu', 'angl', 'angem')):
            return 0.65 * strength - 0.5
        return 0.4 * strength - 0.25
    if low == 'am' and not token[:1].isspace() and left.endswith('u'):
        return -0.85

    # A few document-initial effects, including a Java package declaration.
    if position == 1 and before == 'package' and low == 'com':
        return -2.0
    if position == 0:
        if token == '<|endoftext|>':
            return 3.04
        if token == '\x00':
            return 4.27
        if token == '.\n':
            return 1.95
        if low == 'package':
            return -0.75
        return 0.34 if s[:1].isupper() else 0.12
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = b'', 0
    else:
        _, previous, position = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous.decode('utf-8', 'ignore'), position)
    previous = (previous + prefix.token_bytes[-1])[-128:]
    return (doc, previous, position + 1), float(value)

programs.haiku:
"""Layer-1 MLP down_proj component 161: a "-ang" syllable detector with a "huang" twist.

What it does: it reacts to the spelling "ang" inside a token (ang, angle, sang, Yintang,
Wang, uang, lang ...). The sign and size depend on the letter just before "ang":
  - after u or o (uang, oang: the sound of "huang"/"zhuang"/"ulang") it is strongly positive;
  - after w, i, y or l (wang, iang, lang) it is mildly positive;
  - after a consonant (sang, Gesang, Yintang, Undang, angle after "t"/"n"...) it is negative,
    most strongly after s, n, p, z, and weakly after r, g, j, b, or at a word start (" ang").
Words and characters meaning "emperor" or "yellow" are positive too: Huang, 皇 (emperor),
황, 黄, Emperor. Everything else predicts 0. Only the current token and the previous
token's last letter are read, so it is causal.
"""

READS = ()

ANG_BEFORE = {
    "u": 4.6, "o": 2.5, "w": 1.3, "i": 0.2, "y": 0.2,
    "r": -0.1, "h": 0.0, "l": 0.0, "e": 0.0,
    "t": -0.6, "d": -0.5, "g": -0.5, "j": -0.5, "k": -0.3, "b": -0.2,
    "m": -1.0, "f": -1.7, "c": -1.8, "p": -2.9, "s": -3.0,
    "n": -3.2, "z": -3.6, "-": -3.0, " ": -0.25,
}
ONE_CHAR_HUANG = {"皇": 4.5, "황": 3.8, "黃": 1.4, "黄": 1.0}
HUANG_WORDS = {"huang": 5.7, "hwang": 5.7, "emperor": 1.5, "peror": 1.5}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if word in ONE_CHAR_HUANG:
        return carry, ONE_CHAR_HUANG[word]
    if word in HUANG_WORDS:
        return carry, HUANG_WORDS[word]
    if word == "am":
        return carry, -0.25
    low = token.lower()
    if "ang" not in low:
        return carry, 0.0
    k = low.index("ang")
    if k > 0:
        before = low[k - 1]
    elif token.startswith(" "):
        before = " "
    elif len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = prefix.token_strings[-2][-1:].lower()
    else:
        before = ""
    return carry, ANG_BEFORE.get(before, 0.0)

programs.sol:
"""A local motion/path cue.

Entering, leaving and reaching respond directly. Motion words make a following
source/destination preposition strong, using five prior tokens, including short object phrases.
The cue extends into the next article. Dictionary roots merge English forms;
small extra rules cover partitives, Chinese directions and translated path words.
First tokens and train/training words receive negative offsets.
This is a lexical approximation, not a parser or a word-sense disambiguator.
"""
from functools import lru_cache
import wordnet

READS = ()
BOUNDARY = set("enter penetrate leave depart escape flee reach arrive".split())
TRAVEL = set("move travel walk fly sail drive ride climb swim march wander roam "
             "head rush escort crawl hike proceed advance".split())
TRANSFER = set("send transport transfer deliver carry bring ship dispatch transmit "
               "inject insert import export pour emit release deploy admit "
               "relocate migrate emigrate immigrate".split())
REMOVAL = set("remove withdraw pull take draw".split())
ACCESS = set("access entrance arrival entry departure delivery passage route path "
             "trip journey voyage admission way home".split())
ARTICLES = {"the", "a", "an"}
PATH = {
    "to": .07, "from": .05, "into": .65, "onto": .52,
    "toward": .4, "towards": .5, "through": .47, "across": .29,
    "along": -.23, "around": .16, "at": -.04, "in": -.04,
    "for": 0, "of": 0, "with": 0, "on": -.05,
    "out": .08, "up": .06, "down": .08, "back": .24,
    "away": .13, "off": .16, "over": -.07,
}


@lru_cache(maxsize=100000)
def meaning(word):
    roots = set(wordnet.base_forms(word)) | {word}
    # Current word; then following goal, source, article and route-preposition.
    if roots & BOUNDARY:
        current = .2 if word == "left" else 1.4
        route = 2.3 if "arrive" in roots else .3
        return current, 1.8, 1.4, 1.2, route, True
    if "approach" in roots:
        return (.9 if word.endswith(("ed", "ing", "es")) else 0,
                .3, .8, .5, .3, True)
    if "return" in roots:
        return (.7 if word.endswith(("ed", "ing")) else 0,
                2.3, 2.3, 0, .3, True)
    if "come" in roots:
        return .35, 1.8, .4, 0, .2, True
    if "go" in roots:
        return .6, 1.6, .3, .25, .3, True
    if roots & TRAVEL:
        return 0, 2.6, 1.1, .2, 1, True
    if roots & TRANSFER:
        return 0, 2.1, 1.2, 0, .2, True
    if roots & REMOVAL:
        return 0, .8, .8, 0, 0, True
    if "get" in roots:
        return 0, 1.4, .2, 0, .5, True
    if roots & {"visit", "attend", "explore"}:
        return .8, .4, .2, .3, 0, True
    if roots & {"elect", "assign", "promote", "appoint", "invite", "select"}:
        return 0, 1.3, 0, 0, .1, False
    if roots & {"lead", "guide", "direct", "steer", "navigate", "converge"}:
        return 0, .2, 0, .4, .4, True
    if roots & ACCESS:
        return .15, .6, .7, .2, .3, False
    if word in {"out", "up", "down", "back", "away", "off", "over", "on"}:
        return 0, .6, 1.1, 0, .2, False
    if "verb.motion" in wordnet.categories(word):
        return 0, .2, .2, .05, .05, False
    return 0, 0, 0, 0, 0, False


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = doc, "", []
    _, partial, history = carry
    text = prefix.token_strings[-1]
    token = text.strip().lower()
    joined = bool(text and text[0].isascii() and text[0].isalpha() and partial)
    word = partial + token if joined else token
    alphabetic = word.isascii() and word.isalpha()
    cue = meaning(word) if alphabetic else (0, 0, 0, 0, 0, False)
    value = cue[0] - (.28 if not history else 0)
    older_motion = any(m[-1] for _, m in history[:-1])
    if token in PATH:
        value += PATH[token]
        if history and token not in {"of", "with", "on"}:
            channel = 1 if token == "to" else 2 if token == "from" else 4
            value += history[-1][1][channel]
            lag = max((.7 ** i for i, (_, m) in
                       enumerate(reversed(history[:-1]), 1) if m[-1]), default=0)
            value += (.6 if token == "to" else .3) * lag
        if token == "of" and history and history[-1][0] == "out":
            value += 1.4 + (.9 if older_motion else 0)
        if token == "to" and history:
            if history[-1][0] in {"it", "him", "her", "me", "them", "you", "us"}:
                value += 1 if older_motion else 0
            if history[-1][0] == "way" and any(
                w in {"make", "made", "making", "find", "found"}
                for w, _ in history[:-1]
            ):
                value += .7
    if token in ARTICLES and history:
        value += history[-1][1][3]
        if history[-1][0] in {"into", "toward", "towards", "through", "across"}:
            value += .5
    if token == "of" and history and history[-1][0] in {
        "one", "two", "three", "each", "either", "any", "many", "some"
    }:
        value += .6
    if token in {"train", "trains", "training"}:
        value -= .45
    if token in set("去回赴往"):
        value += 1.5
    elif token in set("进進入出到来來达達从從过過"):
        value += .7
    elif (token and all(ch in "进進入出到去来來往达達离離從从回赴过過前返开開"
                       "下上走了的正在要想能已就再通經经" for ch in token)
          and any(ch in "进進入出到去来來往达達离離回赴过過" for ch in token)):
        value += 1.3
    if token in {"para", "nach", "إلى", "tới", "đến"}:
        value += .6
    if token in {"из", "aus", "от"}:
        value += .2
    if joined and history:
        history = history[:-1]
    history = (history + [(word, cue)])[-5:]
    return (doc, word if alphabetic else "", history), float(value)

"""Approximate the large document-opening responses.

The recognizable cases are initial code declarations, comments/docstrings,
Markdown headings, and chat delimiters. These rules apply after a document
reset, not at every line or chat turn. Two-token opening labels and empty
comment lines get special handling; weak context-dependent activity elsewhere
is omitted.
"""

READS = ()

# Module/import statements and Python function declarations.
CODE_OPENERS = {
    'package': 6.31,
    'from': 5.05,
    'import': 4.23,
    'using': 3.55,
    'def': 4.10,
}


def opening_value(text):
    if text in CODE_OPENERS:
        return CODE_OPENERS[text]
    if text in {'const', 'var', 'module'}:
        return 2.7
    if text in {'class', 'export', 'int'}:
        return 2.0
    if text.startswith('<|') or text in {'<tool_call>', '</tool_call>'}:
        return 2.22
    if text == '#':
        return 4.44
    if text == '##':
        return 4.04
    if text and set(text) == {'#'}:
        return 2.18
    if text.startswith('/*'):
        return 3.3
    if text in {'//', '--'} or text.startswith(('#!/', '#pragma')):
        return 2.2
    if text.startswith('#ifndef'):
        return 3.3
    if text.startswith('#define'):
        return 1.8
    if text.startswith(('"""', "'''")):
        return 3.7
    if text == '<':
        return 1.76
    if text.lower() in {'how', 'why', 'what', 'where', 'when', 'who', 'which'}:
        return 0.9
    if text.isdigit():
        return -0.1
    if text.isspace():
        return 0.15
    return 0.08


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos = 0
        value = opening_value(text)
    else:
        pos = carry[1] + 1
        value = 0.0
        if pos == 1 and carry[2] in {'//\n', '//\r\n'} and text == '//':
            value = 3.18
        # The colon completes the opening label of a titled document.
        if pos == 1 and text == ':':
            if carry[2] == 'Title':
                value = 4.05
            elif carry[2] == 'Question':
                value = 0.94
    return (doc, pos, text), value

"""Approximate boundary strength for short structured lines and statements.

Punctuation determines a boundary strength; indentation, short lines and
assignments amplify it, while comments, prose-like spacing and chat
separators weaken it. Actual and escaped newlines are recognized. Most
ordinary text gets zero. Import and return/declaration lines get a
strong negative value at a bare line break, as do one-value assignments.
Two middle dots and a hyphen have separate positive rules. The previous
token and last 400 characters of the line are reset at document changes.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=16000)
def frequency(word):
    return zipf_frequency(word, 'en')


def predict(s, previous, line):
    if s == '··':
        return 2.0
    if s == '-':
        return 0.12
    newline = '\n' in s or s == '\\n'
    punctuation = not any(c.isalnum() for c in s)
    core = s.replace('\\n', '').strip()
    if newline and not core:
        if s not in ('\n', '\n\n', '\r\n', '\r\n\r\n', '\\n'):
            return 0.0
        code = re.sub(r'^\s*\d+\s*\t', '', line.replace('\\t', '\t'))
        statement = code.lstrip()
        if re.match(r'(from\s+\S+\s+import\b|import\s|package\s)', statement):
            return -2.25
        if re.match(r'(return |var |const |let |raise |yield |throw )', statement):
            return -2.30
        assignment = re.fullmatch(
            r'[A-Za-z_]\w*(?:\.\w+|\[[^\]]+\])*\s*(?:=(?!=)|:=)\s*(\S+)',
            statement)
        if assignment and assignment[1][-1].isalnum() and not any(
                c in statement for c in ('#', '//')):
            return -2.30
        strength = 0.65 if s == '\\n' else 0.73
    elif punctuation and ';' in s:
        strength = 1.40 if '\\' in s else 0.88 if newline else 0.57
        if ')' in s:
            strength -= 0.17 if '\\' in s else 0.35 if newline else 0.02
    elif newline and punctuation and not s.startswith((' ', '\t')):
        if any(c in core for c in "'\""):
            strength = 0.53
        elif ')' in core:
            strength = 0.43
        elif ']' in core:
            strength = 0.47
        elif ',' in core:
            strength = 0.35
        else:
            return 0.0
    elif punctuation and '\\' in s:
        closing = any(c in s for c in "'\")]},")
        if s.startswith(' '):
            strength = 0.0 if closing else 0.05
        else:
            strength = 0.40 if closing else 0.25
    elif s == 'n' and previous.endswith('\\'):
        strength = 0.20
    elif punctuation and not s.startswith((' ', '\t')):
        if '`' in s:
            strength = 0.49
        elif '$' in s:
            strength = 0.26
        elif any(c in s for c in "'\""):
            strength = 0.31 if ',' in s else 0.09
        elif any(c in s for c in ')]}'):
            strength = 0.09
        else:
            return 0.0
    else:
        return 0.0
    q = previous.strip()
    common = frequency(q)
    words = len(line.split())
    factor = 0.20
    factor += 0.58 * ('=' in line)
    factor -= 0.05 * any(c in line for c in '()[];')
    factor -= 0.30 * line.lstrip().startswith(('#', '//', '*'))
    factor += 0.60 * (len(line)-len(line.lstrip()) >= 2)
    factor -= 0.42 * ('\n' in previous or previous.endswith('\\n'))
    factor -= 0.07 * (common >= 4)
    factor += 0.07 * q.isdigit()
    factor += 0.04 * (len(q)==1 and q.isascii() and q.isalpha())
    factor -= 0.26 * previous.startswith(' ')
    factor += 0.31 * (common > 0.5)
    factor -= 0.66 * (previous.startswith('<') or q in (
        'assistant', 'user', 'system'))
    factor += 0.26 * (words <= 8) + 0.21 * (words <= 4)
    return -strength * factor


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, previous, line = carry
    s = prefix.token_strings[-1]
    value = predict(s, previous, line)
    line = (line+s).replace('\\n', '\n').split('\n')[-1][-400:]
    return (doc, s, line), float(value)

"""A sparse approximation of document-edge and opening-format responses.

Most tokens get a near-zero background. Initial boundary markers, NULs,
escaped quotes and ASCII whitespace are positive. Import-like keywords,
heading marks and line-comment openings are negative. An initial 'Title:'
field gets a large negative response at its colon. End markers soon after
punctuation get a decaying positive response. Fine lexical variation is
intentionally omitted; state resets at each document boundary.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        n, first, previous = 0, text, ""
    else:
        _, n, first, previous = carry
        n += 1
    value = -0.003
    if n == 0:
        value = 0.0
        if text == "<|endoftext|>":
            value = 3.125
        elif text == "\x00":
            value = 1.50
        elif text == '\\"':
            value = 1.34
        elif text == "//\n":
            value = -3.15
        elif text == "//":
            value = -0.335
        elif text in {"import", "from", "package"}:
            value = -0.80
        elif text in {"#", "##"}:
            value = -0.76
        elif text.isspace() and text.isascii():
            value = 0.17
    elif text == "<|endoftext|>" and n <= 8:
        if not any(c.isalnum() for c in previous):
            value = 1.84 * math.exp(-0.55 * (n - 1))
    elif n == 1:
        if first == "Title" and text == ":":
            value = -4.265
        elif first.startswith("//") and text.startswith("//"):
            value = -0.795
    return (doc, n, first, text), value

"""A sparse approximation of initial-number and question-label responses.

Short initial numbers get strong full-stop pulses, unlike long numbers/years.
An initial run of ones followed by a two has a separate strong response.
Initial type names, comment openers, curly quotes and word classes get coarse
biases. Question labels and middle-dot leaders have additional rules.
Other text stays near zero. Fine token-specific/contextual variation is omitted.
"""
import re
import math
from functools import lru_cache

READS = ()
TYPES = frozenset(('int', 'integer', 'float', 'double', 'string', 'char',
                   'bool', 'boolean', 'void', 'class', 'function', 'struct'))
PRONOUNS = frozenset(('i', 'you', 'he', 'she', 'it', 'we', 'they', 'them',
                      'my', 'your', 'his', 'her', 'our', 'their'))

@lru_cache(maxsize=16000)
def initial(s):
    w = s.strip()
    if w.isascii() and w.isdigit():
        return 0.13 if w in ('2', '3') else -0.24
    if w in ('int', 'integer'):
        return 1.4 if not s.startswith(' ') else 1.1
    if w in TYPES:
        return 0.8
    if w.startswith(('/*', '//')):
        return 0.6
    if s.startswith('“'):
        return 0.83
    if w.lower() == 'question':
        return 0.75
    if w.lower() in ('which', 'what', 'why', 'how'):
        return 0.35
    if w.lower() in PRONOUNS:
        return -0.40
    if w.lower() in ('a', 'the', 'this', 'that', 'these', 'those'):
        return -0.28
    if w.startswith('<|'):
        return 0.22
    if not w:
        return -0.12
    if w[0] in '([{':
        return 0.13
    if w[0] in ')]},':
        return -0.23
    return -0.13 if w.isascii() and w.islower() else -0.04


def number_stop(number):
    """Short index numbers have stronger boundaries than long numbers/years."""
    number = number.lstrip('0') or '0'
    n = len(number)
    if n == 1:
        d = int(number)
        return 0.0 if d == 0 else min(1.35, 0.65 * math.log1p(d))
    if n == 2:
        return 1.35 if int(number) < 20 else 1.65 if int(number) >= 90 else 2.15
    if n == 3:
        return 1.05 if int(number) >= 900 else 1.75
    return 0.20


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '')
    _, position, start, line = carry
    value = 0.001
    if position == 0:
        value = initial(s)
    elif start.isascii() and start.isdigit():
        if s == '.':
            value = number_stop(start)
        elif s in ('.\n', '.\n\n'):
            value = 0.35 * number_stop(start)
        elif s.isascii() and s.isdigit():
            if len(set(start + s)) == 1:
                value = initial(s)
            elif start.strip('1') == '' and s == '2':
                value = 2.20
            elif position < 4:
                value = 0.25
    heading = re.search(r'(?i)(?:^|\n|#+\s*)(?:question|q)\s*(\d*)$', line)
    if heading:
        if s.isascii() and s.isdigit():
            value = 0.60 if '#' in line else 0.27
        elif heading[1] and s.startswith(('.', ':')):
            value = 0.80 if '#' in line else 0.50
        elif s == ' ':
            value = 0.15
    if s.strip() and set(s.strip()) == {'·'} and len(s.strip()) > 1:
        value = 0.47
    start = start + s if position < 20 else ''
    line = (line + s).split('\n')[-1][-100:]
    return (doc, position + 1, start, line), float(value)

"""Approximate negative pulses for dimension and mass-noun complements.

Use the last two token strings, resetting at document boundaries. Bare nouns
following prepositions/conjunctions respond more than modified nouns. Time
variation, time/space coordinates, generic 'man', and 'speed of light' are
strong cases; other named semantic groups get smaller pulses. A few fixed
phrases and hyphenated coordinate compounds have separate rules. Everything
else is zero: this deliberately leaves small, diffuse activations unexplained.
"""
READS = ()

PREPOSITIONS = set('of in into to from through with by for on about per via '
                   'without like over under at as across beyond before after '
                   'since during throughout between against'.split())
LINKS = PREPOSITIONS | {'and', 'or', 'than', 'including'}
DIMENSIONS = set('temperature age pressure velocity acceleration frequency '
                 'voltage resistance density strain gravity price'.split())
EXTENTS = set('distance height depth volume mass length width weight'.split())
REFERENCES = {'baseline', 'origin', 'boundary'}
SENSES = {'light', 'sound', 'smell', 'taste', 'touch', 'color'}
NATURAL = {'air', 'water', 'heat', 'sunlight', 'weather', 'climate'}
ABSTRACT = set('trade technology money health faith religion god christ spirit '
               'scripture war sport sense hunger addition relation feedback '
               'reality practice society consciousness grace'.split())
SURROUNDINGS = {'environment', 'atmosphere', 'nature', 'ground'}
LIFE_STAGES = {'childhood', 'infancy', 'aging', 'pregnancy'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    doc = prefix.document_ids[-1]
    before, previous = carry[1:] if carry and carry[0] == doc else ('', '')
    state = (doc, previous, word)
    if (token and token[0].isalpha() and previous.isalpha()
            and prefix.position > 0
            and prefix.token_strings[-2][-1:].isalpha()):
        return state, 0.0
    bare = previous in LINKS
    boundary = not previous or not previous[-1:].isalnum()
    if word in {'time', '-time'}:
        if word == '-time':
            if previous in {'displacement', 'velocity', 'position', 'distance'}:
                return state, -6.5
            return state, -2.2 if previous == 'continuous' else 0.0
        if previous == 'of' and before == 'function':
            return state, -6.0
        if previous == 'of' and before in {'passage', 'flow', 'movement',
                                          'evolution', 'direction'}:
            return state, -3.5
        if previous == 'to' and before == 'respect':
            return state, -4.5
        if previous in {'over', 'across', 'through', 'versus', 'vs'}:
            return state, -5.5
        if previous in {'with', 'as'}:
            return state, -4.3
        if previous in {'in', 'into', 'on', 'between', 'before'}:
            return state, -2.7
        if bare or previous in {'take', 'takes', 'is', 'yet', 'have', 'has',
                                      'represents', 'gives', 'experience'}:
            return state, -1.5
        if previous in {'absolute', 'continuous'}:
            return state, -2.7
        return state, -0.35 if boundary else 0.0
    if word in {'space', '-space'}:
        if previous in {'in', 'into', 'through', 'throughout', 'outer', 'free'}:
            return state, -2.8
        return state, -0.8 if bare or boundary else 0.0
    if word in {'man', 'men'}:
        return state, (-2.6 if word == 'man' else -1.0) if bare else 0.0
    if word == 'light' and previous == 'of' and before in {'speed', 'velocity'}:
        return state, -6.0
    if word == 'to' and previous == 'respect':
        return state, -0.38
    if word == 'series':
        return state, -1.8 if previous == 'in' else 0.0
    if word == 'itself' and previous == 'with':
        return state, -2.5
    if word in REFERENCES:
        if previous == 'of':
            return state, -0.35
        if bare:
            return state, -1.8
        return state, -0.6 if previous == 'the' else 0.0
    if word in EXTENTS and previous == 'constant':
        return state, -1.6
    if word in DIMENSIONS | EXTENTS:
        if previous == 'with':
            return state, -2.5
        if bare:
            return state, -0.45 if word in EXTENTS else -1.2
        if word == 'temperature' and previous in {'the', 'a', 'ambient', 'room'}:
            return state, -0.7
        return state, -0.3 if boundary else 0.0
    if word in SURROUNDINGS:
        if word in {'environment', 'atmosphere'} and previous == 'the':
            return state, -1.1
        return state, -0.7 if bare else (-0.25 if previous == 'the' else 0.0)
    if word in {'gender', 'race'}:
        return state, -1.0 if bare or boundary else -0.2
    if word in LIFE_STAGES:
        return state, -1.4 if bare else -0.3
    if word == 'environmental':
        return state, -0.55
    if word in SENSES | NATURAL | ABSTRACT:
        return state, -0.7 if bare else (-0.3 if boundary else 0.0)
    return state, 0.0

programs.haiku:
"""Dimension nouns (time, space, temperature, ...) used bare after a preposition."""
READS = ()
DIMENSION_NOUNS = {" time", " Time", " space", " Space", " temperature", " gravity", " distance",
    " volume", " pressure", " age", " speed", " area", " price", " light", " air", " water",
    " boundary", " man", " Man", " mass", " energy", " density", " length", " height", " depth"}
STRONG_NOUNS = {" time", " Time", " space", " Space", " temperature"}
STRENGTH = {" over": 6, " through": 5, " across": 5, " with": 3, " in": 2, " from": 1.5,
    " is": 1.5, " to": 1, " of": 1, " at": 1, " on": 1, " and": 0.7, ",": 0.7}
DOT = 0.8
GAIN = 0.7
STRONG_GAIN = 1.5
def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if word.strip() and set(word) <= set("·"):
        return None, -DOT
    if word in DIMENSION_NOUNS:
        gain = STRONG_GAIN if word in STRONG_NOUNS else GAIN
        return None, -gain * STRENGTH.get(prev, 0.1)
    return None, 0.0

programs.sol:
"""A document-opening transient, followed by an early-boundary undershoot.

Standalone opening words (especially capitalized ones) get a positive pulse.
Early punctuation and function words get a negative pulse. That pulse fades
with document age, prior stop-mark/line-break tokens, and token repetition.
Whitespace-prefixed openings look more like fragments and have a larger
undershoot. Punctuation fused with a word gets a much smaller undershoot.
These are approximate text rules, not token-specific weights.
"""
import math
import unicodedata as ud
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
ARTICLES = set('a an the'.split())
PRONOUNS = set(('i you he she it we they me him her us them my your his its '
                'our their this that these those who whom which what whose').split())
LINKS = set(('and or but if so because although though while when where '
             'as than then').split())
PREPOSITIONS = set(('in on at to of for from by with without about into over '
                    'under after before between through during within upon '
                    'against').split())
AUXILIARIES = set(('is are was were be been being am do does did have has had '
                  'can could will would shall should may might must cannot not').split())

@lru_cache(maxsize=20000)
def kind(s):
    w = s.strip()
    lower = w.lower()
    if w and w[0] in '.。！？!?':
        return 'sentence'
    if w and w[0] in ',，、':
        return 'comma'
    if '\n' in s:
        return 'newline'
    if not w:
        return 'space'
    if w[0] in ':;：；':
        return 'colon'
    if w[0] in '()[]{}（）':
        return 'bracket'
    for name, words in (('article', ARTICLES), ('pronoun', PRONOUNS),
                        ('link', LINKS), ('preposition', PREPOSITIONS),
                        ('auxiliary', AUXILIARIES)):
        if lower in words:
            return name
    if w.isdigit():
        return 'digit'
    return 'symbol' if not w[0].isalnum() else 'content'

@lru_cache(maxsize=20000)
def opening(s):
    w = s.strip()
    if s.startswith('<|'):
        return 5.76
    if s.startswith(' '):
        return 0.3 if not w else 0.5 + 0.3 * w[0].isupper()
    if not w:
        if s == '\t':
            return 6.4
        return 2.6 + 1.8 * (s.count('\n') > 1) if '\n' in s else 1.0
    c = w[0]
    if w.isdecimal():
        return 0.5
    if c.isalpha():
        name = ud.name(c, '')
        value = 4.2
        if 'LATIN' in name:
            value = 2.7 + 0.31 * zipf_frequency(w.lower(), 'en')
        elif 'CJK' in name:
            value = 5.35
        elif 'CYRILLIC' in name:
            value = 5.83
        value += 2.75 * c.isupper() - 0.77 * (w.isupper() and len(w) > 1)
        value += {'article': -1.38, 'pronoun': -0.73, 'link': -0.57,
                  'preposition': 0.16, 'auxiliary': 0.44}.get(kind(s), 0)
        return value
    if '\ufffd' in w:
        return 1.5
    if c in '.,，。!?！？:;：；' or ud.category(c) in ('Pe', 'Pf'):
        return 0.3
    if c in '#`' or w.startswith(('//', '/*')):
        return 6.8
    if c == '_':
        return 1.5 if any(x.isalpha() for x in w) else 6.8
    value = 3.7 + 0.8 * (ud.category(c) in ('Ps', 'Pi'))
    value += 1.5 * (c in '\"\'')
    value -= 2.4 * any(x in w for x in ')]}')
    return value + 0.85 * ('\n' in s)

AMPLITUDE = {
    'sentence': 1.95, 'comma': 1.12, 'newline': 0.88, 'space': 0.31,
    'colon': 0.46, 'bracket': 0.54, 'article': 0.63, 'pronoun': 0.72,
    'link': 0.70, 'preposition': 0.45, 'auxiliary': 0.58, 'digit': 0.16,
    'symbol': 0.33, 'content': 0.15,
}
MARKS = {'sentence', 'comma', 'newline', 'space', 'colon', 'bracket'}
BOUNDARIES = {'sentence', 'comma', 'newline', 'colon'}

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        scale = (1.87 if s.startswith(' ') else 1.0)
        scale *= 0.75 if s[:1].isalpha() else 1.0
        carry = (doc, 0, 0, {}, False, scale)
    doc, age, sentences, seen, after_boundary, scale = carry
    k = kind(s)
    repeats = min(seen.get(s, 0), 5)
    if age == 0:
        value = opening(s)
    else:
        tau = 28.0 if k in MARKS else 7.06
        pulse = math.exp(-age / tau - 1.02 * sentences - 0.61 * repeats)
        boost = 3.49 if after_boundary and k not in MARKS else 1.0
        amplitude = AMPLITUDE[k]
        if k in MARKS and any(c.isalnum() for c in s):
            amplitude = 0.12
        value = 0.025 - amplitude * pulse * scale * boost
    seen[s] = repeats + 1
    sentences += k in {'sentence', 'newline'}
    return (doc, age + 1, sentences, seen, k in BOUNDARIES, scale), float(value)

programs.haiku:
"""Draft v7: a document-start detector.

Two regimes, both about the first few tokens of a document:

* The first token of a document. Its activation depends only on that token: large and
  positive (about +7) for a capitalised word or code/markup opener ('The', '#', '/*'),
  about +4 for a lower-case or CJK word start, near 0 for a token that continues a
  sentence (leading space) or closes one (',' '.' ')'). The middle-dot run token '··'
  gives +12 wherever it occurs (seen in one training row).

* Rows that begin mid-document (no <|endoftext|> just before the row's first token) get a
  negative push in their first ~40 tokens: strongest on the first sentence end (about
  -3 right after the start, fading over ~25 tokens), weaker on later sentence ends
  (-0.3), and on commas, semicolons, brackets and function words (-0.5 to -1, fading
  within ~10 tokens). Documents that begin after <|endoftext|> get no such push.
"""

import math

READS = ()

SENTENCE_END = (".", "。", "?", "!")
CLOSERS = set(".,:;)!?」】’”")
DOT_RUN = "··"


def _start_value(tok):
    """Activation on a document's first token, a function of that token alone."""
    if tok == "" or tok.isspace():
        return 3.5
    if tok[0] == " ":
        return 0.5
    if tok[0].isdigit():
        return 0.5
    if tok[0].isalpha():
        if tok[0].isupper():
            return 7.0
        return 4.1 if ord(tok[0]) < 0x2E80 else 5.6
    if tok[0] in CLOSERS:
        return 0.0
    return 5.5


def _push(tok, d, ends_before):
    """Negative push at position d >= 1 of a document that begins mid-text."""
    s = tok.strip()
    if s.startswith(SENTENCE_END):
        if ends_before == 0:
            return -3.0 * math.exp(-d / 25)
        return -0.3
    if tok[:1] == " " and s.isalpha():
        return -0.45 * math.exp(-(d - 1) / 8)
    if s and not s[0].isalnum():
        return -0.9 * math.exp(-(d - 1) / 8)
    return 0.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[1]:
        # a new document: it begins mid-text if it starts the row (no end-of-text before it)
        mid_text = len(prefix.token_ids) == 1
        carry = (-1, doc, mid_text, 0)
    d = carry[0] + 1
    _, _, mid_text, ends = carry
    if d == 0:
        new = (0, doc, mid_text, 0)
        return new, (12.0 if tok == DOT_RUN else _start_value(tok))
    if tok.strip().startswith(SENTENCE_END):
        ends_after = ends + 1
    else:
        ends_after = ends
    new = (d, doc, mid_text, ends_after)
    if tok == DOT_RUN:
        return new, 12.0
    if not mid_text or d > 80:
        return new, 0.0
    return new, _push(tok, d, ends)

programs.sol:
"""A local phrase detector, chiefly for recurrence and amounts of time.

Negative responses mark expressions such as 'each one', 'per day', 'a
second', and European apostrophe elisions. 'More than one' is positive.
Only the current and preceding two tokens are needed; document breaks reset
that context. Other text receives zero. Rare multilingual and
longer-context responses are not modeled.
"""
READS = ()

TIME_UNITS = {
    'second', 'minute', 'hour', 'day', 'week', 'month', 'year',
    'decade', 'century', 'millennium', 'moment', 'night', 'morning',
    'afternoon', 'evening', 'semester', 'quarter',
}
NUMBERS = {'one', 'two', 'three', 'four', 'five', 'six', 'seven',
           'eight', 'nine', 'ten', 'eleven', 'twelve'}
DAYS = {'monday', 'tuesday', 'wednesday', 'thursday', 'friday',
        'saturday', 'sunday'}


def response(word, previous, before):
    """Predict a typical signed response for a short phrase."""
    if word == 'one':
        if previous == 'each':
            return -5.5
        if previous == 'every':
            return -2.2
        if previous == 'than' and before == 'more':
            return 2.9
        if previous in {'any', 'some', 'single', 'by'}:
            return -0.6
    if previous == 'than' and before == 'more':
        if word == 'a':
            return 1.1
        if word in NUMBERS:
            return 1.0
    if word in TIME_UNITS or word in DAYS:
        if previous in {'each', 'every', 'per'}:
            if previous == 'per' and word == 'hour':
                return -1.8
            return {
                'each': -3.4, 'every': -2.7, 'per': -3.7,
            }[previous]
        if previous in {'a', 'an'}:
            if word in {'second', 'minute', 'moment', 'hour', 'year'}:
                return {
                    'second': -1.4, 'minute': -2.4, 'moment': -1.8,
                    'hour': -0.9, 'year': -0.95,
                }[word]
            if word in {'day', 'week', 'month'}:
                return -1.7
            return -0.5
        if previous in {'all', 'that', 'next', 'one', 'single', 'whole', 'any'}:
            return {
                'all': -0.95, 'that': -0.6, 'next': -0.3, 'one': -0.3,
                'single': -2.0, 'whole': -1.0, 'any': -1.1,
            }[previous]
        if previous == 'of' and word in {'day', 'year'}:
            if word == 'year' or before in {'time', 'times'}:
                return -2.4
        if previous == 'by' and word in {'day', 'night', 'week', 'year'}:
            return -1.8
    if word.endswith('s') and word[:-1] in TIME_UNITS:
        if previous == 'few':
            return -0.15
    if word in {"'", '’', '᾽'}:
        if previous in {'d', 'de'}:
            return -1.5
        if previous in {'l', 'dell'}:
            return -0.3
        if previous in {'un', 'an', 'all', 'dall', 'n', 'm', 's', 'c', 'o'}:
            return -0.5
    if previous == 'to' and word in {'-night', '-day', '-m'}:
        return {
            '-night': -7.0, '-m': -5.1, '-day': -3.0,
        }[word]
    if word in {'maximum', 'minimum'}:
        if previous in {'a', 'an', 'relative'}:
            return -2.0
    if word == 'average' and previous in {'an', 'on'}:
        return -1.2
    if word == 'member' and previous == 'a':
        return -0.8
    if word == 'se' and previous == 'per':
        return -1.0
    if word in NUMBERS and previous == 'or' and before in NUMBERS:
        return -0.4
    if word == 'forget' and previous in {"'t", 'not'}:
        return 0.8
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous = before = ''
    else:
        _, previous, before = carry
    word = prefix.token_strings[-1].strip().lower()
    value = response(word, previous, before)
    return (document, word, previous), value

"""Opening-token suppression and occupational/calendar compounds.

At a document's opening, predict a modest negative response, repeated while
that opening token repeats. The number 12 and the metadata headers Title:
and Posted on have especially negative opening responses. Initial middle-dot
and caret filler runs are also strongly negative. Away from the opening, read
work/day/time and social/personal-life compounds, including split words and
intervening whitespace. Chinese work/trading days receive the same calendar
response; Chinese reference,
focal, and extreme points have a separate positive response. Everything else is
near zero; this intentionally leaves most lexical variation unexplained.
"""
import re
import unicodedata

READS = ()

LIFE_DOMAINS = {
    'personal', 'work', 'business', 'political', 'cultural',
    'practical', 'social', 'civilian', 'commercial',
}


def opening(token):
    if token == '1':
        return -0.442
    if len(token) >= 2 and set(token) == {'·'}:
        return -2.95
    if len(token) >= 4 and set(token) == {'^'}:
        return -4.92
    if token.startswith('<|'):
        return -0.07
    if token.isdecimal():
        return -0.30
    if all(unicodedata.category(c)[0] in 'PS' for c in token):
        return -0.10
    return -0.24


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        n, previous, initial_run, tail = 0, '', True, b''
    else:
        _, n, previous, initial_run, tail = carry
        initial_run = initial_run and token == previous
    word = token.strip().lower()
    # Read the preceding word, even across token splits or whitespace.
    before = tail.decode('utf-8', errors='ignore').rstrip()
    match = re.search(r'[A-Za-z]+$', before)
    previous_word = match.group() if match else ''
    prev = previous_word.lower()
    value = 0.0
    if initial_run:
        value = opening(token)
    elif n == 1 and previous == '1' and token == '2':
        value = -6.026
    elif n == 1 and previous == 'Title' and token == ':':
        value = -1.748
    elif n == 1 and previous == 'Posted' and token == ' on':
        value = -4.216
    elif word in {'life', '-life'}:
        value = -0.10
        if prev in LIFE_DOMAINS:
            value = 1.2
            if previous_word == 'Personal':
                value = 1.5
        elif prev == 'family':
            value = 0.63
        elif prev in {'public', 'financial', 'intellectual', 'religious'}:
            value = 0.45
    elif word in {'day', 'days'}:
        value = -0.04
        if prev in {'business', 'working'}:
            value = 2.6 if word == 'days' else 2.8
            if token.strip() == 'Days':
                value = 3.3
        elif prev == 'work':
            value = 1.4
        elif prev in {'school', 'study', 'game', 'wedding'}:
            value = 0.3
        elif prev in {'election', 'labour'}:
            value = 0.65
    elif word == 'year' and prev == 'academic':
        value = 1.0
    elif word == 'week' and prev == 'work':
        value = 0.75
    elif word == 'hours' and prev == 'business':
        value = 1.0
    elif word in {'time', 'hours'} and prev == 'working':
        value = 0.6
    elif token in {'日', '日内', '日內'}:
        if before.endswith(('工作', '交易', '营业', '營業')):
            value = 2.8
        elif before.endswith(('宣传', '宣傳')):
            value = 1.7
    elif token == '点' and before.endswith((
        '控制', '基准', '关键', '关注', '焦',
        '起', '终', '高', '低', '最大', '最小', '着力',
    )):
        # Reference points, focal points, and extrema.
        value = 1.5
    tail = (tail + prefix.token_bytes[-1])[-80:]
    return (doc, n + 1, token, initial_run, tail), value

programs.haiku:
"""Layer-1 MLP neuron 174 (down_proj), read as a word detector.

It goes negative on words that begin a new clause or a stock phrase, most strongly right
after a comma, full stop or line break: "Let's" / "Let me", "For example", "According to",
"If you need it, you ...", "..., I ...", "It's", "There's", "In ...". It is also negative
on the stem of a negative contraction ("don't", "won't", "doesn't", "wouldn't"), on a few
words that often come before a fixed phrase ("known", "referred", "right", "such"), on
capital Cyrillic letters that open a sentence, and on the first token of each document.
Everything else is treated as zero."""

READS = ()

# Phrase openers: strongly negative ("Let me", "For example", "Thanks for", "According to").
STOCK_OPENERS = {
    "Let": -1.4, "let": -0.4, "For": -1.2, "Sup": -1.3, "Thank": -1.2,
    "Thanks": -1.2, "According": -1.0, "according": -0.6,
}
# Clause-opening pronouns and adverbs: negative when they start a clause
# (after punctuation or a line break), weaker mid-sentence.
CLAUSE_WORDS = {
    "I": -0.6, "you": -0.9, "You": -0.8, "it": -0.6, "It": -0.5, "we": -0.6,
    "We": -0.5, "there": -0.7, "There": -0.8, "Here": -0.6, "In": -0.5,
    "As": -0.5, "Now": -0.5, "That": -0.5, "What": -0.4,
}
CLAUSE_MID = {
    "I": -0.2, "you": -0.05, "You": -0.1, "it": -0.2, "It": -0.5, "we": -0.2,
    "We": -0.4, "there": -0.6, "There": -0.8, "Here": -0.6, "In": -0.3, "As": -0.3,
    "Now": -0.3, "That": -0.2, "What": -0.2,
}
# Stems of negative contractions, plus a few words that precede fixed phrases.
NEGATIVE_STEMS = {
    "don": -1.0, "Don": -0.9, "won": -1.3, "doesn": -0.9, "didn": -0.7,
    "isn": -0.8, "wouldn": -1.1, "does": -0.5, "known": -0.5, "right": -0.3,
    "e": -0.2, "such": -0.2, "referred": -0.9,
}
PUNCTUATION = set(",.;:!?)\"'")
DOCUMENT_START = -0.4


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    # First token of a document (or of the row): the model resets here.
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, DOCUMENT_START
    before = prefix.token_strings[-2].strip()
    after_break = before == "" or before[-1] in PUNCTUATION
    if word in STOCK_OPENERS:
        return carry, STOCK_OPENERS[word]
    if word in NEGATIVE_STEMS:
        return carry, NEGATIVE_STEMS[word]
    if word in CLAUSE_WORDS:
        if after_break:
            return carry, CLAUSE_WORDS[word]
        return carry, CLAUSE_MID.get(word, 0.0)
    # A capital Cyrillic letter opening a sentence or line.
    if after_break and len(word) == 1 and "А" <= word <= "Я":
        return carry, -1.0
    return carry, 0.0

programs.sol:
"""A spelling-sensitive 'well' response, suppressed in the idiom 'as well'.

Capitalized Well, Wells, and separately tokenized name endings are strong.
Lowercase well is weaker, especially after degree adverbs or do. Commas
immediately after Well or Now retain part of the response.
A few contrasting w-spellings (wipe, whip, wrench, WIP) are negative.
"""
READS = ()
DEGREE = {'very', 'so', 'quite', 'too', 'how', 'equally', 'extremely'}
DO = {'do', 'does', 'did', 'doing', 'done', 'performed'}
BE = {'is', 'are', 'was', 'were', 'be', 'been', 'being'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    prev = previous.strip().lower()
    value = 0.0
    if lower == 'well':
        if first:
            value = 9.3 if word.islower() else 12.0
        elif prev == 'as':
            value = -0.18
        elif word[0].isupper():
            value = 6.8 if token.startswith(' ') else 6.2
        elif not token.startswith(' '):
            value = 2.7 if prev in {'d', 'un'} else 6.8
        elif prev in DEGREE:
            value = 2.7
        elif prev in DO:
            value = 2.2
        elif prev in BE:
            value = 4.5
        elif prev in {'a', 'an'}:
            value = 5.1
        elif prev in {',', '.', '?', '!'}:
            value = 5.8
        else:
            value = 3.9
    elif lower == 'wells':
        value = 7.5 if word[0].isupper() else 5.4
    elif word.isalpha() and not token.startswith(' ') and prev.endswith('w'):
        if lower in {'ell', 'ells', 'elling', 'elled', 'elle', 'elles', 'eller'}:
            value = 9.5
            if prev.endswith('chw'):
                value = 2.7
            elif prev.endswith('ow'):
                value = 6.0
            elif prev.endswith('dw') or (prev.endswith('sw') and lower == 'elling'):
                value = 3.7
            elif lower in {'ell', 'ells'} and not previous[-2:-1].isalpha():
                value = 11.8
        elif lower in {'el', 'elt', 'els', 'ellen'}:
            value = 4.8
        elif lower == 'ip':
            value = -10.0
        elif lower == 'if':
            value = -8.0
        elif lower == 'ulf':
            value = -6.5
    elif lower.startswith('wrench'):
        value = -5.0
    elif lower.startswith('whip'):
        value = -2.6
    elif lower.startswith('wipe') or lower == 'wiping':
        value = -2.0
    elif lower == 'owell':
        value = 5.1
    elif lower == 'swell':
        value = 5.4
    elif lower in {'dwell', 'dwelling', 'swelling'}:
        value = 1.6
    elif lower == 'wel':
        value = 1.1 if token.startswith(' ') else 4.0
        if word[0].isupper():
            value = 2.7
    elif word == ',':
        if previous.strip() == 'Well':
            value = 3.5
        elif previous.strip() == 'Now':
            value = 1.8
    return (document, token), value

"""A spelling/phonetic i-r detector, strongest on short word fragments.

Transliteration lets the same rule cover ir/yr, Cyrillic ир, and Japanese
mi-ra/chi-ra-like transitions. East Asian L is also allowed in this family.
Length and word frequency distinguish fragments from ordinary words.
A match can straddle two tokens or linger into the next word-internal token.
Split 'their' is a negative exception. These are approximate lexical rules,
not a model of the component's full context sensitivity.
"""
import codecs
import re
from functools import lru_cache

import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=50000)
def spelling(text):
    return anyascii(text).lower()


@lru_cache(maxsize=50000)
def frequencies(word):
    english = zipf_frequency(word, 'en')
    other = max(zipf_frequency(word, language) for language in
                ('de', 'es', 'fr', 'it', 'pt', 'tr', 'ru', 'pl'))
    return english, other


def strength(cross, before, after, vowel, nasal, east, suffix_a,
             en, other, frequency, space, letters, prefix_length, repeat):
    # Whole, longer tokens generally have little response.
    if letters > 4:
        return 0.08
    if letters == 4:
        if frequency > 4.4:
            return 0.19
        if east:
            return 0.0
        if en > 4.0:
            return 0.11
        if repeat:
            return 0.44
        return 1.31 if other <= 2.63 else 0.69

    # air/eir/oir-like spellings are much weaker than consonant + ir.
    if vowel:
        return 0.24
    if frequency <= 2.35:
        if suffix_a:
            return 4.68 if after <= 1 else 0.33
        if east:
            return 0.13
        return 1.87 if cross else 0.63

    # An i/y at the preceding token's end, then r in the current token.
    if cross:
        if space:
            return 0.21
        if other <= 1.125:
            return 2.86 if frequency > 3.375 else 1.34
        if after <= 1:
            return 3.62 if frequency <= 3.975 else 5.05
        return 4.08 if frequency <= 3.51 else 2.16

    # ir contained in a short token, or carried from its predecessor.
    if en <= 2.66:
        if after > 2:
            return 1.52 if frequency <= 3.095 else 0.65
        if other <= 4.058:
            return 2.33 if before == 0 else 1.22
        return 2.20 if prefix_length <= 2 else 0.75
    if nasal:
        return 1.92
    if letters <= 2:
        return 1.31
    return 0.81 if frequency <= 5.09 else 0.37


def predict(text, old_word, last_token):
    if not text:
        return old_word, 0.0
    current = spelling(text)
    previous = spelling(last_token)
    continues = bool(text[0].isalpha() and previous
                     and previous[-1].isalpha())
    old = old_word if continues else ''
    runs = re.findall(r'[^\W\d_]+', text)
    word = (old + text if text.isalpha() else
            runs[-1] if runs and text[-1].isalpha() else '')

    # The common possessive behaves differently when artificially split.
    if continues and word.lower() in ('their', 'theirs'):
        if text.lower() not in ('their', 'theirs') and old.lower() != 'their':
            return word, -3.0

    east = bool(regex.search(r'[\p{Han}\p{Hiragana}\p{Katakana}]', text))
    if east and current.startswith('l'):
        current = 'r' + current[1:]
    joined = (previous[-3:] if continues else '') + current
    offset = len(joined) - len(current)
    matches = list(re.finditer('[iy]r', joined))
    if matches and offset - matches[-1].end() > 1:
        matches = []
    # Isolated letters / dotted initials, not arbitrary words ending in i.
    if not matches and len(current.strip(' ._')) == 1:
        if previous.strip(' ._') in ('i', 'y'):
            if current.strip(' ._') == 'r':
                joined, offset = 'ir', 1
                matches = [re.search('ir', joined)]
    if not matches:
        return word[-40:], 0.0

    match = matches[-1]
    position = match.start() - offset
    lag = match.end() <= offset
    cross = position < 0 and not lag
    preceding = joined[max(0, match.start() - 1):match.start()]
    suffix = joined[match.end():]
    after = len(re.match('[a-z]*', suffix).group())
    before = sum(c.isalpha() for c in current[:max(0, position)])
    en, other = frequencies(word or text.strip())
    frequency = max(frequencies(text.strip()))
    value = strength(
        cross, before, after, preceding in 'aeiouy' and bool(preceding),
        preceding in ('m', 'n'), east, suffix.startswith('a'),
        en, other, frequency, text[0].isspace(),
        sum(c.isalpha() for c in current), len(spelling(old)),
        bool(re.search('[iy]r', previous)))
    return word[-40:], value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', b'')
    _, word, last, pending = carry
    data = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(data, 'replace', False)
    word, value = predict(text, word, last)
    return (doc, word, text or last, data[used:]), float(value)

programs.haiku:
"""Layer 1, MLP down-projection, component 177: a document-opening feature.

It is silent inside a document and speaks only on the first token of each document
(or of a packed row). There the attention can see nothing but that token, so the
value is fixed by which token opens the document, and roughly by what kind of token
it is:

- code keywords and preprocessor lines (int, using, import, package, #include)
  push it negative;
- function words and pronouns (The, We, If, A, in, is) sit near zero;
- punctuation, digits and other non-letter openers sit slightly positive;
- a capitalised word of five or more letters (Question, Show, News) is strongly
  positive, and other ordinary words are moderately positive.

Everything else, every position after the first, is 0.
"""

READS = ()

CODE_WORDS = frozenset(
    "int void using var import package def char const function public private class "
    "namespace return static struct use let fn func self from export require new bool "
    "string float double".split()
)
FUNCTION_WORDS = frozenset(
    "the a an and of to in is it this that for with as on be by or at from are was "
    "has have not can should must will if i we they he she you but".split()
)


def _value(token: str) -> float:
    word = token.strip()
    letters = sum(c.isalpha() for c in token)
    if word in CODE_WORDS or word.startswith("#"):
        return -0.4
    if word.lower() in FUNCTION_WORDS:
        return 0.4
    if letters == 0:
        return 0.2
    if word[:1].isupper() and letters >= 5:
        return 2.7
    return 1.7


def step(carry, prefix, upstream):
    starts_document = prefix.position == 0 or (
        prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    if not starts_document:
        return None, 0.0
    return None, float(_value(prefix.token_strings[-1]))

programs.sol:
"""Pulses for separators and explicitly marked code identifiers.

Most text is assigned zero. End-of-text is positive except at a document's first token. Several double-underscore runtime names, self/parent
scope references and test/code annotations are negative. A document-initial
Title: header and paired middle dots have separate negative pulses.
"""
import re

READS = ()

# Runtime metadata spellings shared by Python and JavaScript.
METADATA = {
    'class': -8.0,
    'dirname': -6.6,
    'file': -5.5,
    'module': -5.5,
    'version': -4.0,
    'name': -2.2,
    'main': -2.2,
}
SCOPE = {'self': -7.3, 'Self': -3.5, 'static': -5.6, 'parent': -2.2}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        _, previous, position = carry
    text = prefix.token_strings[-1]
    value = 0.0
    if text == '<|endoftext|>':
        value = -2.86 if position == 0 else 2.84
    elif previous.endswith('__'):
        if text in METADATA:
            value = METADATA[text]
        elif text == 'tests':  # conventionally named test directory
            value = -4.5
        elif text == 'construct':  # PHP magic methods
            value = -2.0
        elif text == 'invoke':
            value = -4.0
    elif text == '::':
        name = re.search(r'(?:^|\W)(self|Self|static|parent)$', previous)
        if name:
            value = SCOPE[name[1]]
    elif previous.rstrip().endswith('@'):
        if text == 'Test':
            value = -1.55
        elif text == 'generated':
            value = -3.1
    elif previous.endswith('#[') and text in {'test', 'inline'}:
        value = -1.95
    elif text == ':' and previous == 'Title' and position == 1:
        value = -4.54
    elif text == '··':
        value = -0.75
    return (doc, text, position + 1), value

"""Detect nonstandard typography and changes of character style.

Fullwidth letters/numerals respond strongly, with diminishing response along a
run and after earlier fullwidth alphanumerics in the document. A fullwidth
parenthesis or curly closing quote is especially strong when its opener was
ASCII. Mathematical letter fragments and a few other display forms get smaller
responses. All other text is near zero, apart from conversation delimiters.
The state resets at document boundaries and decodes incomplete UTF-8 characters.
"""
import codecs
import math
import unicodedata as ud

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, b'', 0, 0, '', None)
    _, pending, run, seen, parentheses, quote = carry
    decoder = codecs.getincrementaldecoder('utf-8')('replace')
    decoder.setstate((pending, 0))
    text = decoder.decode(prefix.token_bytes[-1])
    tail = decoder.getstate()[0]
    chars = text.strip()
    wide = [c for c in chars if ud.decomposition(c).startswith('<wide>')]
    alnum = any(c.isalnum() for c in wide)
    value = 0.0
    if alnum:
        if any(c.isdigit() for c in wide):
            value = (4.0 - 0.44 * bool(run) - 1.06 * math.log1p(run)
                     - 0.71 * math.log1p(seen))
        else:
            value = (4.86 - 2.52 * bool(run) - 0.69 * math.log1p(run)
                     - 0.44 * math.log1p(seen))
