        value = 2.0 if first else max(0.0, value)
    elif wide:
        normal = ud.normalize('NFKC', wide[0])
        if ud.category(wide[0]) == 'Sm':
            value = 0.45
        elif normal in '/\\&%@':
            value = 0.7
        elif ud.category(wide[0]) == 'Ps':
            value = 0.08
