        # This prefix covers mathematical alphabets and musical notation.
        value = 0.65
        if len(tail) == 3:
            name = ud.name((tail + b'\x80').decode('utf-8'), '')
            value = 0.15
            if name.startswith(('MATHEMATICAL BOLD CAPITAL',
                                'MATHEMATICAL BOLD SMALL',
                                'MATHEMATICAL ITALIC')):
                value = 3.1
            elif 'MONOSPACE' in name:
                value = 2.1
    elif tail.startswith((b'\xef\xbc', b'\xef\xbd')):
        value = 0.8  # Incomplete fullwidth character.
    elif any('MATHEMATICAL' in ud.name(c, '') for c in chars):
        value = 0.3
    elif any(ud.decomposition(c).startswith('<font>') for c in chars):
        value = 0.65
    elif not tail and chars in ('ー', '〜'):
        value = 0.4
    elif 'ſ' in chars:
        value = 0.9 if pending else 0.33
    elif chars == '··':
        value = 1.6
    elif any(c in '\u200b\ufe0f' for c in chars):
        value = 0.3
    elif pending or tail:
        value = 0.1

    for c in text:
        if c in '(（':
            parentheses += c
        elif c in ')）':
            if c == '）':
                opener = parentheses[-1:] or None
                value = 3.3 if opener == '(' else (-0.2 if opener else 0.9)
            parentheses = parentheses[:-1]
        elif c in '“„':
            quote = c
        elif c == '"':
            quote = None if quote == '"' else '"'
        elif c == '”':
            value = 1.05 if quote == '"' else (-0.15 if quote == '“' else 0.05)
            quote = None

    if text == '<|im_end|>':
        value = -0.37
    elif text == '<think>':
        value = 0.19
    elif text == '</think>':
        value = 0.1
    return (doc, tail, run + 1 if alnum else 0,
            seen + int(alnum), parentheses, quote), value

"""Local cues for qualifying or specifying an object.

Responds to specific/given/certain/multiple, from/with, and indefinite noun
phrases after prepositions. 'Based on', small-number arguments, and relational
identifier pieces receive extra weight. Separate rules describe negative
start-of-document transients, including initial '12' and formatting prefixes.
This leaves most open-class and longer-context variation unexplained.
"""
import re
READS = ()
QUALIFIERS = {'given': .44, 'certain': .50, 'specific': .56,
              'particular': .28, 'multiple': .49, 'various': .21}
LEXICAL = {'from': .16, 'with': .08, 'in': .02, 'on': .04,
           'within': .04, 'into': .03, 'over': .03, 'about': .05,
           'a': .02, 'an': .03, 'two': .14, 'three': .09,
           'this': .01, 'that': .03, 'some': .02,
           'someone': .30, 'something': .11}
ARTICLES = {'a', 'an'}
PREPOSITIONS = set('of in on at by for from to with into between within '
                   'over under across around through'.split())
AUXILIARIES = set('is are was were be been being have has had am'.split())
COMMANDS = set('solve fix find extract generate describe determine'.split())
FORMAT = {'\t': -1.183, '\\t': -2.217, '//\n': -6.011, '^^^^': -2.977}


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '', None)
    _, position, previous, opening, marker = carry
    w = s.strip().lstrip('._/').lower()
    compound = False
    parts = re.findall(r'[A-Z]?[a-z]+|[A-Z]+(?=[A-Z][a-z]|$)', s)
    if len(parts) > 1:
        relational = [p.lower() for p in parts if p.lower() in PREPOSITIONS]
        if relational:
            w, compound = relational[-1], True
    value = QUALIFIERS.get(w, LEXICAL.get(w, -.005))
    if w in ARTICLES:
        value += .10 * (previous in PREPOSITIONS) + .15 * (previous == 'of')
        value -= .04 * (previous in AUXILIARIES)
    elif w in QUALIFIERS:
        if previous in AUXILIARIES:
            value -= .40
        elif previous in ARTICLES or previous in PREPOSITIONS:
            value += .15
        if w == 'multiple' and previous in ARTICLES:
            value = .05  # 'a multiple' is a number, not an indefinite modifier
    elif w in {'two', 'three'}:
        value += .20 * (previous in PREPOSITIONS)
        value += .30 * (previous in {'from', 'between'})
    elif w in {'this', 'that', 'some', 'someone', 'something'}:
        value += .30 * (previous in COMMANDS)
    if w == 'on' and previous == 'based':
        value = .85
    if position and w in PREPOSITIONS:
        if s.startswith('_'):
            value = max(value, .70)
        elif s.startswith('.') or compound:
            value = max(value, .45)
        elif s[:1].isupper():
            value += .20
