        value = (-.042 if s.startswith('<|') else -.44 if s[:1].isupper()
                 else -.167 if s.isdigit() else -.275)
        marker = s if s in FORMAT else None
    if marker is not None:
        if s == marker:
            value = FORMAT[s]
        else:
            marker = None
    if position == 1 and opening == '1' and s == '2':
        value = -6.447
    if position == 2 and opening == '12' and s == '2':
        value = -2.378
    return (doc, position + 1, w, opening + s if position < 2 else '',
            marker), float(value)

"""A detector for three and closely related written forms.

It responds negatively to 3, three, third, III, and more weakly to
three-sided/three-dimensional words, March, and Wednesday. A 3 in
an HTML character reference has an especially strong response. Separate
surface-form responses cover roughly seven spaces and paired middle dots.
Document-opening tokens use a separate, mostly positive background.
