import math
import unicodedata

READS = ()
DETERMINERS = {'a', 'an', 'the', 'this', 'that', 'these', 'those'}
THREE_RELATED = {
    'tri', 'trig', 'triple', 'triples', 'triplet', 'triplets',
    'triangular', 'cube', 'cubes', 'cubed', 'cubic',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.casefold()
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if start else prefix.token_strings[-2]
    tail = '' if start else carry
    value = -0.002

    if len(word) == 1 and unicodedata.numeric(word, None) == 3:
        value = -0.96
        if previous.isspace():
            value = -0.85
        elif previous and previous[-1].isalpha():
            value = -1.10
        if tail.endswith('&#'):
            value = -2.88
        elif tail.endswith('\\xa'):
            value = -2.8
    elif lower in {'three', 'third', 'thirds'}:
        value = -1.0
    elif lower == 'iii':
        value = -0.85
    elif lower == 'thirty':
        value = -0.52
    elif lower in {'triangle', 'triangles'}:
        value = -0.53
    elif lower in THREE_RELATED:
        value = -0.35
    elif word in {'March', 'Wednesday'}:
        value = -0.41 if word == 'March' else -0.70
    elif token == '··':
        value = 3.02
    elif token.isspace():
        spaces = token.count(' ') + token.count('\N{NO-BREAK SPACE}')
        if spaces:
            value = -0.62 * math.exp(-((spaces - 7) / 2.6) ** 2)
            if '\t' in token or '\n' in token:
                value *= 0.65

    if start:
        if word == '3':
            value = 1.32
        elif word.isnumeric():
            value = 0.0
        elif lower in DETERMINERS:
            value = -0.30
        else:
            value = 0.36 if token.isspace() else 0.55

    return (tail + token)[-12:], value

"""Approximate a document-initial response and a line-indentation response.

Initial words tend positive, especially articles, demonstratives and conjunctions;
numbers, auxiliary verbs and personal pronouns get weaker estimates. These are
coarse grammatical averages, not a prediction of each word's individual response.
Within documents, short even-width runs of spaces after newlines tend negative.
"""
READS = ()
ARTICLES = set('a an the'.split())
DEMONSTRATIVES = set('this that these those'.split())
CONJUNCTIONS = set('and or but nor yet so for'.split())
SUBORDINATORS = set(
    'if unless because although though while since until once whether whereas'.split())
PRONOUNS = set('i me you he him she her it we us they them'.split())
AUXILIARIES = set(
    'is am are was were be been being has have had having do does did doing '
    'can could will would shall should may might must'.split())
NEGATIONS = set('not never cannot no'.split())


def initial(s):
    w = s.strip()
    if not w or w.startswith('<|'):
        return 0.2
    if w.isnumeric():
        return 0.0
    if not any(c.isalpha() for c in w):
        return -0.15
    low = w.lower()
    title = w.istitle()
    if low in ARTICLES:
        return 2.0 if title else 2.65
    if low in DEMONSTRATIVES:
        return 3.0 if title else 4.3
    if low in SUBORDINATORS:
        return 5.5 if title else 2.7
    if low in CONJUNCTIONS:
        return 2.1
    if low in NEGATIONS:
        return -1.1
    if low in PRONOUNS:
        return -0.25 if title else 0.4
    if low in AUXILIARIES:
        return 0.65 if title else 0.25
    if len(w) == 1:
        return 0.4 if title else 0.9
    value = 1.6 if title else 0.8
    if not w.isascii():
        value -= 0.45
    if not w.isalpha():
        value += 0.9
    return value


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if first:
        return None, initial(s)
    value = 0.0
    if s and not s.strip(' ') and len(s) >= 2:
        if len(s) % 2:
            value = 0.04
        elif prefix.token_strings[-2].endswith('\n'):
            previous = prefix.token_strings[-2]
            strength = 1.2
            if previous.isspace():
                strength -= 0.25
            if previous.rstrip().endswith('{'):
                strength += 0.35
            if previous.endswith('\n\n'):
                strength -= 0.4
            value = -strength * min(1.0, 4.0 / len(s))
        else:
            value = -0.05
    return None, value

"""Approximate the component's strongest responses with Dutch spelling rules.

Completed words are compared with English, German and French word frequencies
from wordfreq, with recent words weighted most. In Dutch-looking context, short
open a/o syllables and word-forming prefixes (on-, ont-, be-, ge-) are positive.
Selected function words, especially er and personal pronouns, are negative.
Prefixed words receive small continuation bonuses; punctuation is mostly silent.

A separate Cyrillic у/У rule is stronger after Ukrainian-specific letters.
This is a coarse description, not a table of individual token responses.
"""
import math
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=20000)
def dutch_evidence(word):
    if len(word) < 2 or not word.isalpha():
        return 0.0
    nl = zipf_frequency(word, 'nl')
    other = max(zipf_frequency(word, lang) for lang in ('en', 'de', 'fr'))
    if max(nl, other) < 2.5:
        return 0.0
    return max(-3.0, min(3.0, nl - other - 0.25))


def spelling_value(token, boundary):
    s = token.lower()
    if not re.fullmatch('[a-z]+', s):
        return 0.0
    if boundary:
        if s == 'er':
            return -6.0
        if s in {'je', 'jou', 'jouw', 'jij', 'hun', 'u', 'uw'}:
            return -3.2
        if s == 'dit':
            return -3.0
        if s in {'we', 'wij', 'deze', 'nu', 'kun', 'kan'}:
            return -1.6
        if s == 'met':
            return -2.3
        if s in {'in', 'op', 'aan', 'over', 'bij', 'die'}:
            return 1.7
        if s in {'om', 'onder', 'door'}:
            return 3.3
        if s in {'de', 'het', 'een', 'en', 'van', 'dat', 'is', 'niet', 'te'}:
            return 0.0
        if s == 'on':
            return 9.5
        if s == 'ont':
            return 5.9
        if s == 'be':
            return 6.8
        if s in {'ge', 'gen', 'gem'}:
            return 3.8
        if s in {'ver', 'af', 'her'}:
            return 1.1
        if s == 'toe':
            return 5.0
        if s.startswith('be') and len(s) <= 4:
            return 2.8
        if s.startswith('ge') and len(s) <= 4:
            return 2.1
        if s.startswith(('ing', 'verb')) and len(s) <= 4:
            return 2.5
        if len(s) >= 2 and zipf_frequency(s, 'nl') >= 5.5:
            return 0.3
    if re.fullmatch('[bcdfghjklmnpqrstvwxz]{0,3}[ao]', s):
        if len(s) == 1:
            return 3.9 if boundary else 2.3
        return 5.2 if boundary else 3.4
    quiet_endings = {'en', 'er', 'ing', 'ingen', 'heid', 'lijk',
                     'e', 's', 't', 'ij'}
    if not boundary and s in quiet_endings:
        return 0.0
    if len(s) <= 4:
        if any(v in s for v in ('oe', 'oo', 'aa', 'ui')):
            return 1.7
        first_vowel = next((ch for ch in s if ch in 'aeiou'), '')
        if first_vowel in {'a', 'o'}:
            return 0.7
        if first_vowel in {'i', 'u'}:
            return -0.3
        if first_vowel == 'e':
            return 0.2
    return 0.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', [], False, 0.0, False)
    _, word, evidence, was_letter, echo, ukrainian = carry
    token = prefix.token_strings[-1]
    boundary = not was_letter or not token[:1].isalpha()
    ukrainian = ukrainian or any(ch in token.lower() for ch in 'іїєґ')
    for ch in token:
        if ch.isalpha():
            word += ch.lower()
        elif word:
            evidence = (evidence + [dutch_evidence(word)])[-12:]
            word = ''
    score = sum(e * 0.72 ** i for i, e in enumerate(reversed(evidence)))
    log_odds = max(-30.0, min(30.0, 1.8 * (score - 1.0)))
    gate = 1.0 / (1.0 + math.exp(-log_odds))
    if len(evidence) < 2:
        gate *= len(evidence) / 2.0
    raw = spelling_value(token.strip(), boundary)
    if not boundary:
        raw += echo
        if word.startswith(('be', 'toe')) and len(word) <= 10:
            raw += 0.8
        elif word.startswith(('ge', 'in', 'on')) and len(word) <= 10:
            raw += 0.3
    # The prefix on- ('un-') leaves a small, quickly fading response.
    if boundary:
        echo = 1.0 if token.strip().lower() == 'on' else 0.0
    else:
        echo *= 0.4
    value = gate * raw
    if token in {' у', ' У', 'У'}:
        value = -3.0 if ukrainian else -0.15
    state = (doc, word[-80:], evidence, token[-1:].isalpha(), echo, ukrainian)
    return state, float(value)

"""A solar-spelling feature, not a general detector of astronomy.

Recognize short sun/sol stems and Chinese sun characters. Also recognize
sun/sol when s and its continuation fall in different tokens. Some contrasting
s-initial syllables (six, sax, sill, sock, som), plus Persian saz and Japanese
socks spellings, get negative responses. Complete words such as Sunday and
solution are not treated as short sun/sol fragments.
"""
import re
from anyascii import anyascii

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    prior = anyascii(previous).lower()
    text = prefix.token_strings[-1]
    token = text.strip()
    lower = text.lower()
    roman = anyascii(text).lower()
    stem = re.sub(r'^[^a-z]+', '', lower)
    value = 0.0

    if stem == 'sun':
        value = 4.0
    elif stem == 'sung':
        value = 4.8 if token[:1].isupper() else 2.0
    elif stem == 'sunny':
        value = 2.1
    elif stem == 'solar':
        value = 3.5 if token[:1].isupper() else 2.7
    elif stem in ('sol', 'insol'):
        value = 2.7
        if stem == 'sol' and text.startswith(' '):
            value = 2.2 if token[:1].isupper() else 1.5
    elif stem == 'soil':
        value = -0.65
    elif stem in ('sill', 'sax'):
        value = -1.9

    if text[:1].isalpha() and prior.endswith('s'):
        if lower == 'un':
            value = 5.0
        elif lower in ('ol', 'olar'):
            value = 4.1
        elif lower.startswith('олн'):
            value = 6.5
        elif (re.fullmatch(r'un[a-z]{1,2}', lower)
              and lower[2] not in 'aeiou'):
            value = 3.1
            if lower.startswith('unn') or lower == 'uns':
                value = 6.2
            elif lower.startswith('und'):
                value = 1.0
        elif lower == 'ungen':
            value = 1.3
        elif re.fullmatch(r'ol(?:[ai]|at(?:e|ion)|t|ic)', lower):
            value = 2.1
        elif re.fullmatch(r'(?:[ai]x|ill[sy]?|ocks?)', lower):
            value = -3.0
        elif re.fullmatch(r'o(?:m(?:e|es)?|rt|re|k)', lower):
            value = -1.1
        elif re.fullmatch(r'[ao]z', roman):
            value = -3.5
        elif token == 'از':
            value = -8.5
        elif lower == 'ur':
            value = 1.0

    # Kana spellings of sol and socks, with their first syllable split off.
    if previous.endswith('ソ'):
        if token == 'ル':
            value = 3.5
        elif token == 'ックス':
            value = -7.0

    if token in ('阳', '陽'):
        value = 4.5 if token == '阳' else 5.0
        if previous.endswith('太'):
            value = 10.5
    elif token in ('太阳', '太陽'):
        value = 6.1
    elif token in ('太阳能', '太陽能'):
        value = 2.2
    return (doc, text), value

"""Approximate vowel crowding at word-piece joins.

Case and accents are folded. Extending a Latin vowel run across a token
boundary to at least three vowels produces a negative pulse; its size depends
on the vowel spelling. Cyrillic and Greek joins have smaller, separate rules.
The u in qu is excluded. Two middle dots have a separate positive response.
Everything else stays near zero; word-specific variation is not modeled.
"""
import codecs
import unicodedata

READS = ()
VOWELS = frozenset('aeiouаеёиоуыэюяαεηιουω')
CYRILLIC = frozenset('аеёиоуыэюя')
GREEK = frozenset('αεηιουω')
WEAKER_RUNS = {'eau', 'eou', 'ieu', 'eei', 'uia', 'iei', 'uei'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, pending = '', b''
    else:
        _, tail, pending = carry
    data = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(data, 'replace', False)
    pending = data[used:]
    s = ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                if not unicodedata.combining(c))
    n = 0
    while n < len(s) and s[n] in VOWELS:
        n += 1
    head = s[:n]
    run = tail + head if tail and head else ''
    value = 0.002
    if len(run) >= 3 and run.isascii():
        value = -1.2
        if head.startswith('ia'):
            value = -4.0 if tail.endswith('a') else -2.6
        elif head.startswith('io') and tail[-1] in 'ae':
            value = -4.2
        elif head.startswith('ie'):
            value = {'a': -0.6, 'e': -3.6, 'o': -1.8}.get(tail[-1], -0.6)
        elif tail.endswith('ou') and head[0] in 'ei':
            value = -3.1
        elif tail.endswith('ai'):
            value = -3.5
        elif tail.endswith('au') and head.startswith('a'):
            value = -5.0
        elif run[-3:] in WEAKER_RUNS:
            value = -0.45
    elif len(run) >= 2 and any(c in CYRILLIC for c in run):
        value = -1.0 if run.endswith(('яи', 'ее')) else -0.27
    elif len(run) >= 2 and any(c in GREEK for c in run):
        value = -0.8 if len(run) >= 3 else -0.25
    if text == '··':
        value = 2.13
    if n == len(s):
        tail = (tail + s)[-5:]
    else:
        k = len(s)
        while k and s[k - 1] in VOWELS:
            k -= 1
        tail = s[k:][-5:]
    # The u in qu is consonantal, not an additional vowel.
    if s.endswith('qu'):
        tail = ''
    return (doc, tail, pending), value

"""A code-declaration feature, driven by words, indentation, and syntax.

Variable-binding words get the largest values, especially at indented statement
starts. Built-in types get smaller values, strengthened by declaration modifiers.
Pieces inside identifiers are quiet. Escaped newlines/tabs and numbered source
listings are treated as source formatting. A few C type/namespace continuations
and the paired middle-dot separator have their own small responses. Dollar
signs are strengthened in PHP/Perl declaration contexts; C++/Rust-style const and
mathematical let contexts are damped by simple nearby syntax cues.

This is a lexical/syntactic approximation, not a parser: it cannot know whether a
bare word will continue into a longer identifier at the next token.
"""
import re

READS = ()
BINDINGS = set('const var let auto final Dim'.split())
MODIFIERS = set('public private protected static final const inline virtual '
                'extern volatile readonly constexpr'.split())
#                 inline, line start, indented, after modifier, after final
TYPE_LEVELS = {
    'int':        (0.5, 2.3, 4.6, 1.7, 3.3),
    'long':       (-0.1, 0.4, 2.0, 1.4, 2.2),
    'float':      (0.2, 2.7, 3.9, 2.2, 3.0),
    'char':       (0.04, 1.3, 3.2, 1.6, 2.8),
    'String':     (0.9, 1.9, 5.0, 2.1, 5.6),
    'string':     (-0.1, 1.2, 3.5, 2.0, 3.0),
    'bool':       (0.2, 1.3, 3.1, 1.2, 2.0),
    'unsigned':   (0.1, 0.6, 1.6, 1.4, 1.8),
    'object':     (0.0, 0.15, 0.9, 0.2, 0.7),
}
TYPE_CLASS = {
    'Long': 'long', 'short': 'long',
    'double': 'float', 'decimal': 'float', 'boolean': 'bool',
    'uint': 'unsigned', 'signed': 'unsigned',
}
for _word in ('File', 'Object', 'Integer', 'List', 'Map', 'Set'):
    TYPE_CLASS[_word] = 'object'


def predict(token, before, last):
    text = before.replace('\\n', '\n').replace('\\t', '\t')
    previous = last.replace('\\n', '\n').replace('\\t', '\t')
    word = token.replace('\\$', '$').strip().lstrip('(')
    leading = token[:1].isspace()
    tabbed = token.startswith('\t')
    attached = (not leading and not token.startswith('(') and text and
                (text[-1].isalnum() or text[-1] == '_'))
    line = text.rsplit('\n', 1)[-1]
    line = re.sub(r'^\s*\d+\t', '', line)
    at_start = not line.strip()
    gap = re.search(r'[ \t]+$', text)
    punctuation = text.rstrip()[-1:]
    statement = punctuation in ('{', '}', ';')
    paren = punctuation == '(' or token.startswith('(')
    indented = bool(gap and (at_start or statement))
    words = re.findall(r'[A-Za-z_]+', previous)
    modifier = words[-1] if words else ''

    if word in BINDINGS:
        if attached:
            return 0.0
        if token.startswith('('):
            return 0.2
        if word == 'const' and punctuation == ',':
            return 0.5
        if word == 'let' and modifier == 'if':
            return 3.9
        if word == 'final' and modifier == 'static':
            return 1.8
        if indented:
            value = 7.8 if word != 'final' else 6.1
        elif tabbed:
            value = 4.6 if at_start or line.strip().isdigit() else 0.1
            if word == 'auto' and at_start:
                value = 8.0
        elif leading:
            value = 0.1
        elif paren:
            value = 3.8 if word != 'final' else 0.0
        elif statement:
            value = 6.6 if word == 'var' else 5.3
        elif at_start:
            value = 4.9
        else:
            value = 3.2 if word == 'const' else 0.6
        if word == 'const' and re.search(
                r'std::|template\s*<|\b(typename|constexpr|struct|impl)\b', text):
            value *= 0.35
        if word == 'let' and any(c in text for c in '←∀→'):
            value *= 0.3
        return value

    kind = TYPE_CLASS.get(word, word)
    if kind in TYPE_LEVELS:
        inline, bare, indent, modified, final = TYPE_LEVELS[kind]
        if attached:
            return -0.1
        if kind == 'string' and text.endswith('::'):
            return 2.4
        if modifier in MODIFIERS:
            return final if modifier == 'final' else modified
        if indented or (tabbed and at_start):
            return indent
        if at_start and not leading:
            return bare
        if paren:
            return 0.5 if token.startswith('(') else max(0.4, bare * 0.7)
        return inline

    if word == '$':
        value = 0.05
        if leading and indented:
            value = 6.4 if statement else 2.8
        elif modifier in ('my', 'our', 'local', 'state'):
            return 5.6
        elif modifier in ('public', 'private', 'protected', 'static'):
            value = 3.3
        elif not leading and at_start and (statement or '<?php' in text):
            value = 5.4
        elif paren:
            value = 0.4
        elif not leading and indented:
            value = 1.3
        return value * (0.2 if '\\$' in token else 1.0)
    if word in ('def', 'fn', 'func', 'Sub', 'function') and not attached:
        if word == 'function':
            return 2.0 if at_start or statement or modifier == 'async' else 0.1
        return 0.5 if at_start or indented or tabbed else 0.2
    if word in ('import', 'package', 'using') and not attached:
        return 0.4 if word == 'package' else 0.1
    if token == '_t' and re.search(
            r'\b(size|ssize|ptrdiff|u?int(?:8|16|32|64|max)?|u?intptr|off|time)$', text):
        return 2.8
    if word == '::' and re.search(
            r'(?:^|\n)[ \t]*(?:\d+\t)?[ \t]*std$', text):
        return 1.2
    if token == '··':
        return 1.63
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, last = '', ''
    else:
        _, before, last = carry
    token = prefix.token_strings[-1]
    value = predict(token, before, last)
    return (doc, (before + token)[-256:], token), float(value)

"""Approximate the component's prominent immediate-repetition response.

Repeated Han characters receive a frequency-modulated pulse: uncommon
characters and familiar doubled forms are emphasized. Kana, Hangul, words
and symbols use simpler scales. Case/punctuation-normalized matches and
Han suffix overlaps receive weaker pulses. Spaces, digits and incomplete
UTF-8 fragments are mostly suppressed; document starts have small baselines.
This captures local repetition, not all token-specific activation variation.
"""
import regex
import math
from wordfreq import get_frequency_dict
from opencc import OpenCC
from functools import lru_cache

READS = ()
CHINESE_FREQUENCIES = get_frequency_dict("zh")
SIMPLIFY = OpenCC("t2s")


@lru_cache(maxsize=8192)
def kind(text):
    if not text:
        return 'space'
    if regex.fullmatch(r'\p{Script=Han}+', text):
        return 'han'
    if regex.fullmatch(r'[\p{Script=Hiragana}\p{Script=Katakana}ー]+', text):
        return 'kana'
    if regex.fullmatch(r'\p{Script=Hangul}+', text):
        return 'hangul'
    if text.isdecimal():
        return 'digit'
    if text.isalpha():
        return 'word'
    return 'symbol'


@lru_cache(maxsize=4096)
def han_pulse(text):
    if len(text) != 1:
        return 2.2
    text = SIMPLIFY.convert(text)

    def frequency(word):
        # Zipf scale: one point is a tenfold difference in corpus frequency.
        return max(0.0, 9 + math.log10(
            CHINESE_FREQUENCIES.get(word, 1e-9)))

    return max(0.5, min(13.0, 10.1 - 0.9 * frequency(text)
                        + 0.6 * frequency(text + text)))


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1].strip()
    category = kind(text)
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if first:
        return None, (-0.2 if category == 'digit' else
                      -0.3 if category == 'han' and len(text) == 1 else -0.05)
    old = prefix.token_strings[-2].strip()
    if not text or '\ufffd' in text or '\ufffd' in old:
        return None, 0.0
    exact = prefix.token_ids[-1] == prefix.token_ids[-2]
    if exact or text == old:
        if category == 'han':
            value = han_pulse(text)
        elif category == 'kana':
            value = 5.6 if len(text) == 1 else 4.2
        elif category == 'hangul':
            value = 3.1
        elif category == 'word':
            value = (0.5 if len(text) == 1 else
                     1.0 if exact else 0.5)
        elif category == 'digit':
            value = -0.01
        elif set(text) == {'^'}:
            value = 2.5
        else:
            value = 0.15 if text.isascii() else 0.5
    elif text.casefold() == old.casefold():
        value = 0.3
    elif category == 'han' and old.endswith(text):
        value = 0.37 * han_pulse(text)
    else:
        letters = ''.join(c for c in text if c.isalpha())
        previous = ''.join(c for c in old if c.isalpha())
        value = 0.15 if letters and letters.lower() == previous.lower() else 0.0
    return None, value

"""An Italian-context word-piece signal, not a general language detector.

Completed words supply decaying frequency evidence for Italian versus five
other languages. In Italian context, demonstrative and quantity stems are
negative; short consonant fragments are positive. Other spelling classes
get small fitted averages. State resets at document boundaries.
"""
import math
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('it', 'en', 'fr', 'es', 'pt', 'de')
PARTS = re.compile(r'[A-Za-zÀ-ÖØ-öø-ÿ]+|[^A-Za-zÀ-ÖØ-öø-ÿ]+')
FUNCTION_WORDS = set(
    'il lo la i le gli di da a in con su per tra fra e o che '
    'del dello della dei degli delle al alla nel nella '
    'non si se ma un'.split()
)


@lru_cache(maxsize=30000)
def evidence(word):
    frequencies = [zipf_frequency(word.lower(), lang) for lang in LANGUAGES]
    peak = max(frequencies)
    if peak < 3:
        return (0.,) * 6
    return tuple(max(-3., f - peak) for f in frequencies)


def lexical_response(piece, word, previous_word):
    """Negative Italian pronoun families versus positive spelling fragments."""
    w = word.lower()
    s = piece.strip().lower()
    if w in ('que', 'quei') or w.startswith('quegl'):
        return -5.6
    if w == 'quell':
        return -6.3
    if w.startswith('quell'):
        return -10.56
    if w == 'quel':
        return -7.31
    if w == 'qu':
        return -4.8
    if w.startswith('quest'):
        return -2.42
    if w.startswith('quant'):
        return -3.5
    if w.startswith('qual'):
        return -.48
    if s in ("'", '’'):
        return 3.5 if previous_word.lower() == 'c' else -1.2
    if s in FUNCTION_WORDS:
        return .047
    if s in ('una', 'uno'):
        return -1.21
    if s in ('stato', 'stata', 'stati', 'state'):
        return -1.9
    if not s.isalpha() or not s.isascii():
        return -.01
    if len(s) == 1 and s not in 'aeiou':
        return 1.155
    if s[-1:] not in 'aeiou' and len(s) <= 5:
        return .525
    return .103 if len(s) <= 3 else .228


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', (0.,) * 6)
    _, word, scores = carry
    previous_word = word
    piece = prefix.token_strings[-1]
    for part in PARTS.findall(piece):
        if part[0].isalpha():
            word += part
        elif word:
            scores = tuple(.85 * s + e
                           for s, e in zip(scores, evidence(word)))
            word = ''
    word = word[-50:]
    italian_margin = scores[0] - max(scores[1:])
    gate = max(0., math.tanh((italian_margin - .5) / 2.))
    value = gate * lexical_response(piece, word, previous_word)
    return (document, word, scores), value
